<script setup lang="ts">
import { computed, inject, ref } from 'vue'
import Callbacks from '../../../classes/callbacks'
import Message from '../../../classes/message'
import { getConfig } from '../../../runtime/config'
import { useImkitStore } from '../../../stores/imkit'
import SubmitSvg from '../../svgs/SubmitSvg.vue'

defineOptions({
  inheritAttrs: false
})

const props = defineProps<{ content: any }>() // eslint-disable-line @typescript-eslint/no-explicit-any
const inputValue = ref('')
inputValue.value = props.content.text
const emailFormatError = ref(false)
const imkit = useImkitStore()
const callbacks = computed((): Callbacks => getConfig().callbacks)
const messageId = inject('messageId') as string
const message = computed((): Message | undefined =>
  imkit.messageMultiLists.get(imkit.selectedRoomId)?.main?.map.get(messageId)
)
const handle = () => {
  if (!message.value) return
  if (props.content.completed) {
    return
  }
  if (props.content.subtype === 'email') {
    const regex = /^\w+([-+.]\w+)*@\w+([-.]\w+)*\.\w+([-.]\w+)*$/
    if (!regex.test(inputValue.value)) {
      emailFormatError.value = true
      return
    }
    emailFormatError.value = false
  }
  callbacks.value.flexMessageInputSubmitted(message.value, inputValue.value)
}
</script>

<template>
  <div class="flex items-center gap-2 rounded bg-white p-2" v-bind="$attrs">
    <input
      v-model="inputValue"
      class="w-full focus:outline-none"
      :placeholder="$t(`Request.Message.${content.subtype}.placeholder`)"
      @keypress.enter="handle"
    />
    <button
      :disabled="!inputValue"
      class="rounded-lg p-[6px] disabled:cursor-not-allowed disabled:bg-gray-400"
      :class="{ 'bg-[#02b13f]': !content.completed }"
      @click="handle"
    >
      <SubmitSvg v-if="!content.completed" />
      <img
        v-else
        width="20"
        height="20"
        src="../../../assets/icon_check.png"
        alt=""
      />
    </button>
  </div>
  <div v-if="emailFormatError" class="mt-2 text-[#fe4d4f]">
    {{ $t('emailFromatError') }}
  </div>
</template>
