<script setup lang="ts">
import { FolderPlus, Megaphone } from 'lucide-vue-next'
import {
  computed,
  onMounted,
  onUnmounted,
  ref,
  watch,
  type Component
} from 'vue'
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { vOnClickOutside } from '@vueuse/components'

interface Props {
  massTextingEnabled?: boolean
}

const { massTextingEnabled = false } = defineProps<Props>()

const emit = defineEmits<{
  createFolder: []
  massTexting: []
}>()

interface ActionItem {
  key: string
  icon: Component
  labelKey: string
  action: () => void
}

// Data-driven action list
const actions = computed<ActionItem[]>(() => {
  const items: ActionItem[] = []

  if (massTextingEnabled) {
    items.push({
      key: 'massTexting',
      icon: Megaphone,
      labelKey: 'massTexting',
      action: () => emit('massTexting')
    })
  }

  items.push({
    key: 'createFolder',
    icon: FolderPlus,
    labelKey: 'createFolder',
    action: () => emit('createFolder')
  })

  return items
})

// Float button icon: use FolderPlus if createFolder exists, otherwise first action's icon
const floatButtonIcon = computed(() => {
  const hasCreateFolder = actions.value.some(
    (item) => item.key === 'createFolder'
  )
  if (hasCreateFolder) return FolderPlus
  return actions.value[0]?.icon ?? FolderPlus
})

const floatButtonRef = ref<HTMLElement>()
const isDragging = ref(false)
const hasDragged = ref(false)
const dragInitiated = ref(false)
const dragStartX = ref(0)
const dragStartY = ref(0)
const buttonPosition = ref<{ x: number; y: number } | null>(null)
const showActionMenu = ref(false)
const windowWidth = ref(window.innerWidth)
const isMobile = computed(() => windowWidth.value <= 640)

const DRAG_THRESHOLD = 5
const MIN_DISTANCE_FROM_EDGE = 12
const BUTTON_SIZE = 48
const INITIALIZATION_DELAY = 100 // ms - wait for DOM to settle

const snapToEdge = (
  x: number,
  y: number,
  containerWidth: number,
  containerHeight: number
) => {
  const centerX = x + BUTTON_SIZE / 2
  const centerY = y + BUTTON_SIZE / 2

  const distanceToLeft = centerX
  const distanceToRight = containerWidth - centerX
  const distanceToTop = centerY
  const distanceToBottom = containerHeight - centerY

  const minDistance = Math.min(
    distanceToLeft,
    distanceToRight,
    distanceToTop,
    distanceToBottom
  )

  let snappedX = x
  let snappedY = y

  if (minDistance === distanceToLeft) {
    snappedX = MIN_DISTANCE_FROM_EDGE
    snappedY = Math.max(
      MIN_DISTANCE_FROM_EDGE,
      Math.min(y, containerHeight - BUTTON_SIZE - MIN_DISTANCE_FROM_EDGE)
    )
  } else if (minDistance === distanceToRight) {
    snappedX = containerWidth - BUTTON_SIZE - MIN_DISTANCE_FROM_EDGE
    snappedY = Math.max(
      MIN_DISTANCE_FROM_EDGE,
      Math.min(y, containerHeight - BUTTON_SIZE - MIN_DISTANCE_FROM_EDGE)
    )
  } else if (minDistance === distanceToTop) {
    snappedY = MIN_DISTANCE_FROM_EDGE
    snappedX = Math.max(
      MIN_DISTANCE_FROM_EDGE,
      Math.min(x, containerWidth - BUTTON_SIZE - MIN_DISTANCE_FROM_EDGE)
    )
  } else if (minDistance === distanceToBottom) {
    snappedY = containerHeight - BUTTON_SIZE - MIN_DISTANCE_FROM_EDGE
    snappedX = Math.max(
      MIN_DISTANCE_FROM_EDGE,
      Math.min(x, containerWidth - BUTTON_SIZE - MIN_DISTANCE_FROM_EDGE)
    )
  }

  return { x: snappedX, y: snappedY }
}

const handleDragStart = (event: TouchEvent | MouseEvent) => {
  if (!isMobile.value) return

  const clientX = 'touches' in event ? event.touches[0].clientX : event.clientX
  const clientY = 'touches' in event ? event.touches[0].clientY : event.clientY

  if (floatButtonRef.value) {
    const button = floatButtonRef.value.querySelector('button')
    if (!button) return

    const buttonRect = button.getBoundingClientRect()
    const isTouchingButton =
      clientX >= buttonRect.left &&
      clientX <= buttonRect.right &&
      clientY >= buttonRect.top &&
      clientY <= buttonRect.bottom

    if (!isTouchingButton) return

    hasDragged.value = false
    isDragging.value = false
    dragInitiated.value = true

    const rect = floatButtonRef.value.getBoundingClientRect()
    const container = floatButtonRef.value.parentElement
    if (container) {
      const containerRect = container.getBoundingClientRect()
      if (!buttonPosition.value) {
        buttonPosition.value = {
          x: rect.left - containerRect.left,
          y: rect.top - containerRect.top
        }
      }
      dragStartX.value = clientX - rect.left
      dragStartY.value = clientY - rect.top
    }
  }
}

const handleDragMove = (event: TouchEvent | MouseEvent) => {
  if (!isMobile.value || !floatButtonRef.value || !dragInitiated.value) return

  const clientX = 'touches' in event ? event.touches[0].clientX : event.clientX
  const clientY = 'touches' in event ? event.touches[0].clientY : event.clientY

  const container = floatButtonRef.value.parentElement
  if (!container) return

  const containerRect = container.getBoundingClientRect()

  if (!hasDragged.value) {
    const rect = floatButtonRef.value.getBoundingClientRect()
    const initialTouchX = rect.left + dragStartX.value
    const initialTouchY = rect.top + dragStartY.value
    const deltaX = Math.abs(clientX - initialTouchX)
    const deltaY = Math.abs(clientY - initialTouchY)

    if (deltaX > DRAG_THRESHOLD || deltaY > DRAG_THRESHOLD) {
      hasDragged.value = true
      isDragging.value = true
      const button = floatButtonRef.value.querySelector('button')
      if (button) {
        button.style.pointerEvents = 'none'
      }
    } else {
      return
    }
  }

  if (!isDragging.value) return

  const relativeX = clientX - containerRect.left - dragStartX.value
  const relativeY = clientY - containerRect.top - dragStartY.value

  const containerWidth = containerRect.width
  const containerHeight = containerRect.height

  buttonPosition.value = {
    x: Math.max(0, Math.min(relativeX, containerWidth - BUTTON_SIZE)),
    y: Math.max(0, Math.min(relativeY, containerHeight - BUTTON_SIZE))
  }

  event.preventDefault()
}

const handleDragEnd = () => {
  if (!isMobile.value || !floatButtonRef.value) return

  const button = floatButtonRef.value.querySelector('button')
  if (button) {
    button.style.pointerEvents = ''
  }

  if (isDragging.value && buttonPosition.value) {
    const container = floatButtonRef.value.parentElement
    if (!container) {
      isDragging.value = false
      hasDragged.value = false
      dragInitiated.value = false
      return
    }

    const containerRect = container.getBoundingClientRect()
    const containerWidth = containerRect.width
    const containerHeight = containerRect.height

    const snapped = snapToEdge(
      buttonPosition.value.x,
      buttonPosition.value.y,
      containerWidth,
      containerHeight
    )
    buttonPosition.value = snapped
  }

  isDragging.value = false
  hasDragged.value = false
  dragInitiated.value = false
}

const handleFloatButtonClick = () => {
  if (actions.value.length === 1) {
    // Single action: trigger directly
    actions.value[0].action()
  } else {
    showActionMenu.value = !showActionMenu.value
  }
}

const handleActionClick = (action: ActionItem) => {
  action.action()
  showActionMenu.value = false
}

// Event handlers for drag
const handleTouchMove = (e: TouchEvent) => handleDragMove(e)
const handleMouseMove = (e: MouseEvent) => handleDragMove(e)
const handleTouchEnd = () => handleDragEnd()
const handleMouseUp = () => handleDragEnd()

const initializeMobilePosition = () => {
  if (floatButtonRef.value) {
    const container = floatButtonRef.value.parentElement
    if (container) {
      const containerRect = container.getBoundingClientRect()
      buttonPosition.value = {
        x: containerRect.width - BUTTON_SIZE - MIN_DISTANCE_FROM_EDGE,
        y: containerRect.height - BUTTON_SIZE - MIN_DISTANCE_FROM_EDGE
      }
    }
  }
}

const addDragListeners = () => {
  document.addEventListener('touchmove', handleTouchMove, { passive: false })
  document.addEventListener('mousemove', handleMouseMove)
  document.addEventListener('touchend', handleTouchEnd)
  document.addEventListener('mouseup', handleMouseUp)
}

const removeDragListeners = () => {
  document.removeEventListener('touchmove', handleTouchMove)
  document.removeEventListener('mousemove', handleMouseMove)
  document.removeEventListener('touchend', handleTouchEnd)
  document.removeEventListener('mouseup', handleMouseUp)
}

const handleResize = () => {
  windowWidth.value = window.innerWidth
}

// Computed properties for template
const shouldUseStaticPosition = computed(
  () => !isMobile.value || !buttonPosition.value
)

const containerClasses = computed(() => ({
  'right-3 bottom-3': shouldUseStaticPosition.value
}))

const containerStyles = computed(() => {
  if (isMobile.value && buttonPosition.value) {
    return {
      left: `${buttonPosition.value.x}px`,
      top: `${buttonPosition.value.y}px`,
      right: 'auto',
      bottom: 'auto',
      transform: isDragging.value ? 'scale(1.1)' : 'scale(1)'
    }
  }
  return {}
})

const closeActionMenu = () => {
  showActionMenu.value = false
}

// Watch for mobile/desktop mode changes
watch(isMobile, (newIsMobile, oldIsMobile) => {
  if (newIsMobile && !oldIsMobile) {
    setTimeout(() => {
      initializeMobilePosition()
      addDragListeners()
    }, INITIALIZATION_DELAY)
  } else if (!newIsMobile && oldIsMobile) {
    removeDragListeners()
    buttonPosition.value = null
    isDragging.value = false
    hasDragged.value = false
    dragInitiated.value = false
  }
})

onMounted(() => {
  window.addEventListener('resize', handleResize)

  if (isMobile.value) {
    setTimeout(() => {
      initializeMobilePosition()
      addDragListeners()
    }, INITIALIZATION_DELAY)
  }
})

onUnmounted(() => {
  window.removeEventListener('resize', handleResize)
  removeDragListeners()
})
</script>

<template>
  <div
    ref="floatButtonRef"
    v-on-click-outside="closeActionMenu"
    data-id="room-list-float-button"
    role="toolbar"
    aria-label="Floating action button"
    :aria-grabbed="isDragging"
    class="absolute flex flex-col items-end gap-2 transition-transform"
    :class="containerClasses"
    :style="containerStyles"
  >
    <div
      class="relative"
      @touchstart.passive="handleDragStart"
      @mousedown="handleDragStart"
    >
      <transition name="slide-fade">
        <div
          v-if="showActionMenu && actions.length > 1"
          data-id="room-list-float-button-action-menu"
          class="absolute right-0 bottom-14 transform-gpu flex-col items-stretch gap-1 rounded-lg bg-white p-1.5 text-base text-gray-800 shadow-md dark:bg-zinc-800 dark:text-gray-200"
        >
          <div
            v-for="item in actions"
            :key="item.key"
            class="flex cursor-pointer items-center justify-start gap-2 rounded p-2 hover:bg-gray-100 hover:dark:bg-zinc-700"
            @click="handleActionClick(item)"
          >
            <component :is="item.icon" class="h-6 w-6" />
            <span class="whitespace-nowrap">{{ $t(item.labelKey) }}</span>
          </div>
        </div>
      </transition>

      <button
        class="flex h-12 w-12 cursor-pointer items-center justify-center rounded-full bg-slate-500 shadow-md hover:scale-110 hover:transform hover:transition sm:group-hover:flex"
        aria-label="Open action menu"
        :aria-expanded="showActionMenu"
        @click.stop="handleFloatButtonClick"
      >
        <component :is="floatButtonIcon" :size="30" class="text-white" />
      </button>
    </div>
  </div>
</template>

<style scoped>
.slide-fade-enter-from {
  transform: translateY(20px);
  opacity: 0;
}
.slide-fade-enter-active {
  transition: all 0.15s ease-in-out;
}
.slide-fade-enter-to {
  transform: translateY(0);
  opacity: 1;
}
.slide-fade-leave-from {
  transform: translateY(0);
  opacity: 1;
}
.slide-fade-leave-active {
  transition: all 0.15s ease-in-out;
}
.slide-fade-leave-to {
  transform: translateY(20px);
  opacity: 0;
}
</style>
