<script setup lang="ts">
import { computed } from 'vue'
import { useModal } from 'vue-final-modal'
import { useI18n } from 'vue-i18n'
import { PaymentMessage } from '../classes/message'
import { getUid } from '../runtime/uid'
import formatCurrency, { Currency } from '../utils/formatCurrency'
import PaymentDetailModal from './PaymentDetailModal.vue'
import PaymentRequestDetailModal from './PaymentRequestDetailModal.vue'

const props = defineProps<{ message: PaymentMessage }>()

const { t, locale } = useI18n()

const uid = computed(() => getUid())
const isRequest = computed(() => props.message.paymentType === 'request')
const isPayer = computed(() => uid.value === props.message.payer.id)
const paymentStatusMessage = computed(() => {
  if (isRequest.value) {
    return isPayer.value
      ? t('paymentRequestedFromYou', [props.message.payee.nickname])
      : t('paymentRequestedFrom', [props.message.payer.nickname])
  } else {
    return isPayer.value
      ? t('paymentPaidTo', [props.message.payee.nickname])
      : t('paymentCompleted', [props.message.payer.nickname])
  }
})

const { open: openPaymentModal } = useModal({
  component:
    isPayer.value && props.message.paymentType === 'request'
      ? PaymentDetailModal
      : PaymentRequestDetailModal,
  attrs: {
    uid: uid.value,
    paymentId: props.message.paymentId,
    paymentType: props.message.paymentType,
    payer: props.message.payer,
    payee: props.message.payee,
    ...(isPayer.value && props.message.paymentType === 'request'
      ? { availableMethods: [...(props.message.availableMethods || [])] }
      : {})
  }
})

const onClickPaymentCollection = () => {
  openPaymentModal()
}
</script>

<template>
  <div class="flex min-w-[268px] flex-col justify-center">
    <img
      class="mx-auto my-6 h-[72px] w-[72px] object-contain"
      src="../assets/money.png"
      alt="Money Icon"
    />
    <hr class="w-full border-b-[2px] border-[#e5e5e5]" />
    <div class="m-[14px]">
      <p class="text-sm font-medium">{{ paymentStatusMessage }}</p>
      <p class="flex items-baseline">
        <span class="mr-1 text-[18px] font-medium">
          {{ props.message.currency.toUpperCase() }}
        </span>
        <span class="text-[34px] font-medium">{{
          formatCurrency(
            Number.parseInt(props.message.value, 10),
            props.message.currency as Currency
          )
        }}</span>
      </p>
      <p class="text-xs font-normal text-[#6B7280]">
        {{ new Date(props.message.timestamp).toLocaleString(locale) }}
      </p>
      <button
        class="text-sm mt-6 w-full font-medium text-[#02b13f]"
        @click="onClickPaymentCollection"
      >
        {{ $t('paymentViewDetails') }}
      </button>
    </div>
  </div>
</template>
