<script setup lang="ts">
// import { ref } from 'vue'
import { ref } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'
import { useImkitStore } from '../stores/imkit'
import AlertSvg from './svgs/AlertSvg.vue'
import CloseSvg from './svgs/CloseSvg.vue'
import LoadingSvg from './svgs/LoadingSvg.vue'

const vfm = useVfm()
const imkit = useImkitStore()
const isLoading = ref(false)

const props = defineProps<{ roomId: string }>()

const deleteRoom = async () => {
  isLoading.value = true
  try {
    await imkit.hideMessagesFromUserInRoom(props.roomId)
    await imkit.updateRoomPrefs({
      roomId: props.roomId,
      prefs: {
        hidden: true
      }
    })
    vfm.closeAll()
    if (imkit.selectedRoomId === props.roomId) {
      imkit.$patch({
        selectedRoomId: ''
      })
    }
  } catch (error) {
    console.error('Error deleting room:', error)
  } finally {
    isLoading.value = false
  }
}
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-white dark:bg-zinc-800 rounded-xl p-5 flex flex-col items-center gap-5 max-w-[350px]"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div class="w-full">
      <button
        class="ml-auto flex items-center justify-center"
        @click="vfm.closeAll()"
      >
        <CloseSvg class="h-7 w-7" />
      </button>
    </div>
    <AlertSvg />
    <div
      class="text-center text-base font-medium text-stone-800 dark:text-stone-300"
    >
      {{ $t('chatroomDeleteConfirmationTitle') }}
    </div>
    <div class="text-base font-normal text-stone-700 dark:text-stone-400">
      {{ $t('chatroomDeleteConfirmationMessage') }}
    </div>
    <div class="flex w-full gap-3">
      <button
        class="h-10 w-full rounded-md border border-gray-200 text-gray-800 dark:border-stone-400 dark:text-stone-400"
        @click="vfm.closeAll()"
      >
        {{ $t('cancel') }}
      </button>
      <button
        class="flex h-10 w-full items-center justify-center gap-2 rounded-md text-white"
        :class="isLoading ? 'cursor-not-allowed bg-red-300' : 'bg-red-500'"
        @click="deleteRoom"
      >
        <LoadingSvg
          v-if="isLoading"
          class="h-4 w-4"
          :class="isLoading ? 'fill-red-300! text-white!' : 'fill-red-500'"
        />
        {{ $t('delete') }}
      </button>
    </div>
  </vue-final-modal>
</template>
