<script setup lang="ts">
import FlexMessageComponent from './FlexMessageComponent.vue'
defineProps<{ content: any }>() // eslint-disable-line @typescript-eslint/no-explicit-any
const transformSize = (size: string) => {
  const sizes: { [size: string]: string } = {
    none: '0',
    xs: '2px',
    sm: '4px',
    md: '8px',
    lg: '12px',
    xl: '16px',
    xxl: '20px'
  }
  return sizes[size] ?? size
}
</script>

<template>
  <div
    class="flex"
    :class="{
      'flex-col': content.layout === 'vertical',
      'flex-row': content.layout === 'horizontal',
      'flex-row items-baseline': content.layout === 'baseline'
    }"
    :style="{
      backgroundColor: content.backgroundColor ?? '#00000000',
      borderColor: content.borderColor,
      borderWidth: content.borderWidth,
      borderRadius: content.cornerRadius,
      width: content.width,
      maxWidth: content.maxWidth,
      height: content.height,
      maxHeight: content.maxHeight
    }"
  >
    <flex-message-component
      v-for="(c, index) in content.contents"
      :key="index"
      :content="c"
      :style="
        content.layout === 'vertical'
          ? {
              marginTop: c.margin
                ? transformSize(c.margin)
                : index === 0
                  ? 0
                  : transformSize(content.spacing)
            }
          : {
              marginLeft: c.margin
                ? transformSize(c.margin)
                : index === 0
                  ? 0
                  : transformSize(content.spacing)
            }
      "
    />
  </div>
</template>

<style scoped></style>
