import axios, {
  AxiosHeaders,
  type AxiosInstance,
  type AxiosRequestConfig
} from 'axios'
import { useModal, useVfm } from 'vue-final-modal'
import UnauthorizedModal from '../components/UnauthorizedModal.vue'
import { getImkitStore } from '../stores/imkit'
import { getConfig } from './config'
import { clearSignedUrlCache } from './signedUrlStore'
import { resolveToken } from './token'

enum RequestType {
  Start,
  End
}

let _axios: AxiosInstance | null = null

function handleRequest(type: RequestType, config: AxiosRequestConfig) {
  const { url } = config
  const path = url?.split('?')[0]
  if (!path) return
  getImkitStore().mergeInto('isRequesting', {
    [path]: type === RequestType.Start ? new Date() : null
  })
}

const refetchToken = async (): Promise<void> => {
  // Host-provided token provider: ask it to mint a fresh token. Success ends here.
  if (getConfig().getToken && (await resolveToken(true))) return
  // No provider, or the provider could not produce a token: the session is dead.
  if (localStorage.getItem('imkit-token')) {
    localStorage.removeItem('imkit-token')
  }
  const vfm = useVfm()
  vfm.closeAll()
  const { open } = useModal({
    component: UnauthorizedModal
  })
  open()
}

const buildHeaders = (token: string): AxiosHeaders =>
  new AxiosHeaders({
    'IM-Authorization': token,
    'IM-Client-Key': getConfig().clientKey,
    'x-timezone': Intl.DateTimeFormat().resolvedOptions().timeZone,
    'accept-language': navigator.language
  })

export const initAxios = (): AxiosInstance => {
  const instance = axios.create({
    baseURL: getConfig().domain,
    timeout: 10000
  })
  instance.interceptors.request.use(
    async (requestConfig) => {
      handleRequest(RequestType.Start, requestConfig)
      const token = await resolveToken()
      requestConfig.headers = buildHeaders(token)
      return requestConfig
    },
    (error) => {
      handleRequest(RequestType.End, error.config)
      return Promise.reject(error)
    }
  )
  instance.interceptors.response.use(
    (response) => {
      handleRequest(RequestType.End, response.config)
      return response
    },
    async (error) => {
      handleRequest(RequestType.End, error.config)
      if (error.response?.status === 401) {
        const tokenBefore = getConfig().token
        await refetchToken()
        const tokenAfter = getConfig().token
        if (tokenBefore !== tokenAfter) {
          clearSignedUrlCache()
        }
        error.config.headers = buildHeaders(tokenAfter)
        return axios.request(error.config)
      }
      return Promise.reject(error)
    }
  )
  _axios = instance
  return instance
}

export const getAxios = (): AxiosInstance => {
  if (!_axios) throw new Error('imkit runtime not initialized (axios)')
  return _axios
}

export const _resetAxiosForTests = (): void => {
  _axios = null
}
