import dayjs from 'dayjs'
import {
  computed,
  nextTick,
  onMounted,
  onUnmounted,
  ref,
  watch,
  type ComputedRef,
  type Ref
} from 'vue'
import Message from '../classes/message'
import type Room from '../classes/room'
import type Settings from '../classes/settings'
import { getConfig } from '../runtime/config'
import { getSocket } from '../runtime/socket'
import { getUid } from '../runtime/uid'
import { useImkitStore } from '../stores/imkit'

type UseMessageListStateOptions = {
  room: Ref<Room | undefined>
  scrollEl: Ref<HTMLElement | null>
}

type ScrollAlign = 'start' | 'center' | 'end' | 'nearest'

type VirtualizerLike = {
  readonly scrollOffset: number
  readonly scrollSize: number
  readonly viewportSize: number
  scrollToIndex: (
    index: number,
    opts?: { align?: ScrollAlign; smooth?: boolean; offset?: number }
  ) => void
  scrollTo: (offset: number) => void
}

type ScrollToBottomOptions = {
  smooth?: boolean
}

export type UseMessageListStateReturn = {
  isInitialLoaded: Ref<boolean>
  isLatestMessageVisible: Ref<boolean>
  isNearBottom: () => boolean
  isPrepending: Ref<boolean>
  isRequesting: ComputedRef<boolean>
  isScrollToBottomVisible: ComputedRef<boolean>
  onVlScroll: (offset: number) => void
  reloadData: (roomId: string, resetInitialLoaded?: boolean) => Promise<void>
  scrollToBottom: (options?: ScrollToBottomOptions) => Promise<void>
  setVl: (el: unknown) => void
  sortedMessages: ComputedRef<Message[]>
  tobottom: () => Promise<void>
  totop: () => Promise<void>
  vl: Ref<VirtualizerLike | null>
}

const BOTTOM_OFFSET_THRESHOLD = 24

export const useMessageListState = ({
  room,
  scrollEl
}: UseMessageListStateOptions): UseMessageListStateReturn => {
  const imkit = useImkitStore()
  const config = getConfig()

  const selectedRoomId = computed(() => imkit.selectedRoomId)
  const settings = computed((): Settings => config.settings)
  const isRequesting = computed(
    () => !!imkit.isRequesting[`/rooms/${imkit.selectedRoomId}/messages/v3`]
  )
  const sortedMessages = computed((): Message[] => {
    const typingMessages = Object.keys(imkit.isTyping)
      .filter((key) => !imkit.blockedUsers[key])
      .map(
        (key) =>
          new Message({
            _id: key,
            messageType: 'typing',
            sender: {
              _id: key
            }
          })
      )
    return (
      imkit.messageMultiLists
        .get(imkit.selectedRoomId)
        ?.main?.array()
        .concat(typingMessages) ?? []
    )
  })
  const realMessages = computed(
    () => imkit.messageMultiLists.get(imkit.selectedRoomId)?.main?.array() ?? []
  )
  const lastRealMessage = computed(() => realMessages.value.at(-1))
  const navigationTargetId = computed(() => imkit.navigationTargetId)
  const isNavigatingToMessage = computed(() => imkit.isNavigatingToMessage)

  const vl = ref<VirtualizerLike | null>(null)
  const setVl = (el: unknown) => {
    vl.value = (el as VirtualizerLike | null) ?? null
  }
  const isInitialLoaded = ref(false)
  const isLatestMessageVisible = ref(false)
  const isAwayFromBottom = ref(false)
  const isNavigating = ref(false)
  const isBackgroundRefreshing = ref(false)
  const isReconnectResyncing = ref(false)
  // Rooms whose reconnect recovery was deferred (reader in history, another
  // loader in flight, …). Keyed by room so a deferral recorded for one room is
  // never consumed by a spurious resync of another after a room switch.
  const pendingResyncRoomIds = ref<ReadonlySet<string>>(new Set())
  const initialUnreadCount = ref(0)
  const isPrepending = ref(false)

  const markPendingResync = (roomId: string) => {
    if (pendingResyncRoomIds.value.has(roomId)) return
    pendingResyncRoomIds.value = new Set(pendingResyncRoomIds.value).add(roomId)
  }
  const clearPendingResync = (roomId: string) => {
    if (!pendingResyncRoomIds.value.has(roomId)) return
    const next = new Set(pendingResyncRoomIds.value)
    next.delete(roomId)
    pendingResyncRoomIds.value = next
  }

  let prevContainerHeight = 0
  let wasAtBottom = false
  let visibilityHiddenAt = 0

  const isNearBottom = () => {
    if (!vl.value) return false
    return (
      vl.value.scrollSize - vl.value.scrollOffset - vl.value.viewportSize <
      BOTTOM_OFFSET_THRESHOLD
    )
  }

  // Corner scroll-to-bottom button (ported from imkit-ios-sdk `bottomButton`):
  // visible only when scrolled away from bottom AND the latest-message banner
  // is hidden — the two affordances are mutually exclusive, as on iOS.
  const isScrollToBottomVisible = computed(
    () => isAwayFromBottom.value && !isLatestMessageVisible.value
  )

  const scrollToBottom = async ({
    smooth = false
  }: ScrollToBottomOptions = {}) => {
    isLatestMessageVisible.value = false
    isAwayFromBottom.value = false
    if (!vl.value) return
    const last = sortedMessages.value.length - 1
    if (last < 0) return
    const scrollOptions = smooth
      ? ({ align: 'end', smooth } as const)
      : ({ align: 'end' } as const)
    vl.value.scrollToIndex(last, scrollOptions)
    await nextTick()
    vl.value.scrollToIndex(last, scrollOptions)
  }

  const resizeObserver = new ResizeObserver((entries) => {
    const newHeight = entries[0].contentRect.height
    if (prevContainerHeight && vl.value) {
      if (wasAtBottom) {
        void scrollToBottom()
      } else {
        const delta = prevContainerHeight - newHeight
        if (Math.abs(delta) > 1) {
          vl.value.scrollTo(vl.value.scrollOffset + delta)
        }
      }
    }
    prevContainerHeight = newHeight
  })

  const TOP_THRESHOLD_FACTOR = 1.5
  const TOP_THRESHOLD_MIN = 200
  const BOTTOM_EDGE_THRESHOLD = 100
  let wasAtBottomEdge = false

  // ChatRoom.vue swaps rooms in-place (no unmount) via reloadData, so the
  // closure-level scroll flags above persist across switches; reset them when
  // the selected room changes.
  watch(selectedRoomId, () => {
    wasAtBottomEdge = false
    wasAtBottom = false
    prevContainerHeight = 0
    isAwayFromBottom.value = false
  })

  const getScrollSize = () => vl.value?.scrollSize ?? 0
  const getClientSize = () => vl.value?.viewportSize ?? 0
  const getTopThreshold = () =>
    Math.max(getClientSize() * TOP_THRESHOLD_FACTOR, TOP_THRESHOLD_MIN)

  const onVlScroll = (offset: number) => {
    if (!vl.value) return
    const nearBottom = isNearBottom()
    if (settings.value.scrollAnchoringEnabled) {
      wasAtBottom = nearBottom
    }
    const atTop = offset < getTopThreshold()
    const atBottomEdge =
      offset + getClientSize() >= getScrollSize() - BOTTOM_EDGE_THRESHOLD
    if (atTop) void ensureTopLoaded()
    if (atBottomEdge && !wasAtBottomEdge) void tobottom()
    wasAtBottomEdge = atBottomEdge
    isAwayFromBottom.value = !nearBottom
  }

  const shouldChainTop = () => {
    if (isPrepending.value) return false
    if (isNavigating.value || isNavigatingToMessage.value) return false
    if (isBackgroundRefreshing.value) return false
    if (!vl.value) return false
    const roomId = room.value?.id
    const total = imkit.numberOfTotalMessages.get(imkit.selectedRoomId)
    if (!roomId || total === undefined) return false
    if (sortedMessages.value.length >= total) return false
    return vl.value.scrollOffset < getTopThreshold()
  }

  const ensureTopLoaded = async () => {
    if (isPrepending.value) return
    while (true) {
      const before = sortedMessages.value.length
      await totop()
      if (sortedMessages.value.length === before) break
      if (!shouldChainTop()) break
    }
  }

  const totop = async () => {
    if (isNavigating.value || isNavigatingToMessage.value) return
    if (isBackgroundRefreshing.value) return

    const roomId = room.value?.id
    const totalMessages = imkit.numberOfTotalMessages.get(imkit.selectedRoomId)
    if (!roomId || totalMessages === undefined) return
    if (sortedMessages.value.length >= totalMessages) return

    const firstRealMessage = sortedMessages.value.find(
      (message) => !message.id.startsWith('unread-divider-')
    )
    isPrepending.value = true
    try {
      const messages = await imkit.loadMessages({
        roomId,
        beforeMessageId: firstRealMessage?.id
      })
      if (messages && messages.length > 0) {
        const hasLastRead = !!room.value?.lastReadMessageId[getUid()]
        if (
          initialUnreadCount.value > 0 &&
          settings.value.enableReadReceipt &&
          hasLastRead
        ) {
          await imkit.insertUnreadMessage(initialUnreadCount.value)
        }
        // virtua :shift re-anchors visible scroll on prepend; no explicit
        // scrollToIndex(messages.length) needed anymore
      }
      await waitForPaint()
    } finally {
      isPrepending.value = false
    }
  }

  // Resolves once no load for `path` is in flight; used to retry a forward
  // page that collided with a concurrent load (e.g. a reconnect resync).
  const waitForRequestIdle = (path: string) =>
    new Promise<void>((resolve) => {
      if (!imkit.isRequesting[path]) {
        resolve()
        return
      }
      const stop = watch(
        () => imkit.isRequesting[path],
        (pending) => {
          if (pending) return
          stop()
          resolve()
        }
      )
    })

  const tobottom = async () => {
    if (isNavigating.value || isNavigatingToMessage.value) return

    const roomId = room.value?.id
    if (!roomId) return

    isLatestMessageVisible.value = false

    const maxAttempts = 3
    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      const cache = imkit.messageMultiLists.get(imkit.selectedRoomId)
      if (cache?.main == cache?.tail) return

      // Anchor on the last real message: sortedMessages appends typing
      // placeholders whose id is the typing user's uid — not a message id the
      // server could resolve. bypassTotalGuard: we only get here while
      // main !== tail — a real inter-segment gap — and after a bg-suspend the
      // cached numberOfTotalMessages is stale, which would short-circuit this
      // forward heal into an empty page.
      const page = await imkit.loadMessages({
        roomId,
        afterMessageId: lastRealMessage.value?.id,
        bypassTotalGuard: true
      })
      if (page !== null) return
      // null = skipped: a concurrent load (e.g. a reconnect resync) held the
      // endpoint and nothing was fetched. Wait for it to settle and retry —
      // it may itself have healed the gap, which the loop re-checks above.
      await waitForRequestIdle(`/rooms/${roomId}/messages/v3`)
      if (room.value?.id !== roomId) return
    }
    // Exhausted retries with the gap still unhealed: surface it — silence here
    // is indistinguishable from "already at the latest".
    console.warn(
      `[imkit] tobottom gave up after ${maxAttempts} colliding loads; forward gap in room ${roomId} not healed`
    )
  }

  const waitForPaint = () =>
    new Promise<void>((resolve) =>
      requestAnimationFrame(() => requestAnimationFrame(() => resolve()))
    )

  const finishLoad = async (
    roomId: string,
    numberOfUnread: number,
    resetInitialLoaded: boolean,
    gapUnhealed = false
  ) => {
    const uid = getUid()
    const hasLastRead = !!room.value?.lastReadMessageId[uid]
    const hasUnread = settings.value.enableReadReceipt && numberOfUnread > 0
    const shouldShowDivider = hasUnread && hasLastRead
    // A background resync (resetInitialLoaded=false, e.g. a socket reconnect)
    // with nothing new must not disturb the unread divider the reader may be
    // using as a place marker, nor zero the count that re-inserts it on
    // prepend — a 2s WiFi blip would otherwise delete it mid-read.
    const keepUnreadDivider = !resetInitialLoaded && numberOfUnread === 0
    if (!keepUnreadDivider) {
      initialUnreadCount.value = numberOfUnread
    }
    // Never acknowledge messages the user cannot have seen: a reconnect
    // recovery can run while the tab is hidden (socket re-auth in a background
    // window). Same convention as the live-message path; the <60s visibility
    // return marks the room read once the user actually comes back.
    // gapUnhealed extends the same guarantee to a reader AT the tail when the
    // disconnect gap was too wide for the bounded backfill: the fetched latest
    // page is shown, but an unfetched hole still sits above it, so advancing
    // lastRead would acknowledge messages still buried in that hole. The
    // receipt is sent later, once forward paging merges the segments.
    const canMarkRead = typeof document === 'undefined' || !document.hidden
    if (hasUnread && canMarkRead && !gapUnhealed) {
      imkit.updateLastRead(roomId)
    }
    if (shouldShowDivider) {
      await imkit.insertUnreadMessage(numberOfUnread)
    } else if (!keepUnreadDivider) {
      imkit.removeUnreadMessage()
    }
    if (room.value?.isSuperuser) {
      imkit.getBlockList(room.value.id)
    }
    for (const message of imkit.deliveringMessages.values()) {
      if (message.roomId === roomId) {
        imkit.pushMessage(message)
      }
    }
    await waitForPaint()
    if (shouldShowDivider && resetInitialLoaded) {
      const unreadDividerId = `unread-divider-${selectedRoomId.value}`
      const index = sortedMessages.value.findIndex(
        (message) => message.id === unreadDividerId
      )
      if (index !== -1) {
        vl.value?.scrollToIndex(index, { align: 'start' })
        isInitialLoaded.value = true
        return
      }
    }
    // Anchor to the bottom on an initial load; on a background resync
    // (resetInitialLoaded=false, e.g. a socket reconnect) only follow the tail
    // when the user is already near the bottom — don't yank a reader of history.
    if (resetInitialLoaded || isNearBottom()) {
      scrollToBottom()
    }
    isInitialLoaded.value = true
  }

  // Returns the room's unread count, or null when a load was skipped because
  // it collided with an in-flight request — nothing was recovered and the
  // caller must retry instead of treating the room as up to date.
  const fetchAndLoadMessages = async (
    roomId: string,
    bypassTotalGuard = false
  ): Promise<number | null> => {
    // The reconnect gap is "fetched latest page ↔ pre-fill tail segment":
    // anchor on the pre-fill tail's newest message so the backfill stops once
    // they share a segment. Keying on segment count alone would burn the page
    // budget on permanently disjoint jump-to-message residue every reconnect.
    const tailAnchorId = bypassTotalGuard
      ? (imkit.messageMultiLists.get(roomId)?.tail?.tail?.id ?? null)
      : null
    await imkit.fetchRoom(roomId)
    if (imkit.selectedRoomId !== roomId) return 0
    const numberOfUnread = room.value?.numberOfUnread ?? 0

    // On a reconnect recovery the cached numberOfTotalMessages is stale (the dead
    // socket never bumped it), so the latest-page refetch must bypass the
    // stale-total short-circuit; on a normal initial load the guard is wanted.
    const latestPage = await imkit.loadMessages({
      roomId,
      ...(bypassTotalGuard && { bypassTotalGuard })
    })
    if (latestPage === null) return null
    if (imkit.selectedRoomId !== roomId) return numberOfUnread

    const maxPages = 10
    let pages = 0
    // Keep paging backward while either we're short of the unread count OR (on
    // a reconnect recovery only) the latest page landed as a disjoint segment
    // from the pre-fill tail — a gap larger than one page opened during the
    // disconnect, which the single latest page can't bridge. The gap counts as
    // closed once the pre-fill tail's newest message shares a segment with the
    // new tail; stale jump-to-message residue keeps the segment count > 1
    // forever and must not retrigger the backfill. Bounded by maxPages so a
    // huge gap still terminates.
    const hasDisjointGap = () => {
      if (!bypassTotalGuard || !tailAnchorId) return false
      const multi = imkit.messageMultiLists.get(roomId)
      if (!multi || (multi.length ?? 1) <= 1) return false
      return !multi.tail?.contains(tailAnchorId)
    }
    while (
      (realMessages.value.length < numberOfUnread || hasDisjointGap()) &&
      pages < maxPages
    ) {
      const firstRealMessage = realMessages.value.find(
        (message: Message) => !message.id.startsWith('unread-divider-')
      )
      if (!firstRealMessage) break

      const prevCount = realMessages.value.length
      const page = await imkit.loadMessages({
        roomId,
        beforeMessageId: firstRealMessage.id,
        ...(bypassTotalGuard && { bypassTotalGuard })
      })
      if (page === null) return null
      if (realMessages.value.length === prevCount) break
      if (imkit.selectedRoomId !== roomId) return numberOfUnread
      pages++
    }
    return numberOfUnread
  }

  // fetchAndLoadMessages with one retry after a colliding in-flight load
  // settles. A null ("skipped, nothing recovered") coerced to 0 unread would
  // drop the divider and skip updateLastRead off a load that never ran; a
  // second null means something is still busy — defer to the pending-resync
  // machinery rather than loop.
  const fetchAndLoadMessagesSettled = async (
    roomId: string,
    bypassTotalGuard = false
  ): Promise<number | null> => {
    const first = await fetchAndLoadMessages(roomId, bypassTotalGuard)
    if (first !== null) return first
    await waitForRequestIdle(`/rooms/${roomId}/messages/v3`)
    if (imkit.selectedRoomId !== roomId) return null
    return fetchAndLoadMessages(roomId, bypassTotalGuard)
  }

  const backgroundRefresh = async (roomId: string) => {
    isBackgroundRefreshing.value = true
    try {
      const numberOfUnread = await fetchAndLoadMessagesSettled(roomId)
      if (imkit.selectedRoomId !== roomId) return
      if (numberOfUnread === null) {
        markPendingResync(roomId)
        return
      }
      await finishLoad(roomId, numberOfUnread, true)
    } catch (error) {
      console.error('Background refresh failed:', error)
    } finally {
      isBackgroundRefreshing.value = false
    }
  }

  const reloadData = async (roomId: string, resetInitialLoaded = true) => {
    const cachedList = imkit.messageMultiLists.get(roomId)
    const hasCachedMessages = cachedList?.main && cachedList.main.length > 0

    if (hasCachedMessages && resetInitialLoaded) {
      imkit.clearChatRoom()
      imkit.removeUnreadMessage()
      backgroundRefresh(roomId)
      return
    }

    if (resetInitialLoaded) {
      isInitialLoaded.value = false
    }
    imkit.clearChatRoom()
    let numberOfUnread: number | null = 0
    try {
      numberOfUnread = await fetchAndLoadMessagesSettled(roomId)
    } finally {
      if (numberOfUnread === null) {
        markPendingResync(roomId)
      } else {
        await finishLoad(roomId, numberOfUnread, resetInitialLoaded)
      }
    }
  }

  // True while the open room is scrolled to its newest segment (main === tail).
  // A latest-page reload sets main to the newest segment, so it is only safe to
  // run — without yanking the reader — when they are already at the tail.
  const isAtTail = computed(() => {
    const multi = imkit.messageMultiLists.get(selectedRoomId.value)
    return !!multi?.main && multi.main === multi.tail
  })

  // Non-destructively backfill the open room after the socket was dead: refetch
  // the latest page and merge it onto the cached list (no clearChatRoom → no
  // flicker). insert+merge heals BOTH a tail gap and an interior gap — a message
  // older than the cached tail that a live message arriving right after reconnect
  // sealed off (the canonical "A and C shown, B dropped" symptom) — which a
  // tail-only forward-fill cannot reach. finishLoad then advances lastRead when
  // unread remains (so the recovered tail's read receipt is sent and the badge
  // doesn't resurrect) and only follows the tail when the reader is near bottom.
  const softFillOpenRoom = async (roomId: string) => {
    const multi = imkit.messageMultiLists.get(roomId)
    // Reading history (main is an older segment): a latest-page reload would
    // move main to the newest segment and yank the reader to the bottom. Defer
    // until they return to the tail; resyncRooms still refreshes the list entry.
    if (multi?.main && multi.main !== multi.tail) {
      markPendingResync(roomId)
      return
    }
    const mainBefore = multi?.main ?? null
    const readerParked = vl.value ? !isNearBottom() : false
    const numberOfUnread = await fetchAndLoadMessages(roomId, true)
    if (numberOfUnread === null) {
      // Collided with an in-flight load: nothing was recovered — retry once it
      // clears instead of advancing lastRead over a still-missing gap.
      markPendingResync(roomId)
      return
    }
    if (imkit.selectedRoomId !== roomId) return
    // A reader scrolled up inside one merged segment passes the main!==tail
    // check above, but when the gap is too wide for the bounded backfill the
    // fetched latest page stays disjoint and becomes main — collapsing their
    // rendered history to one page. Give them their segment back and finish
    // the heal once forward paging merges the segments at the tail.
    // …but only when the reader's segment is still in the chain: when merge()
    // absorbed it into the fetched page its messages live on in the new main,
    // and restoring the consumed (detached) segment would deadlock the heal —
    // main === tail could never become true again.
    const multiAfter = imkit.messageMultiLists.get(roomId)
    if (
      readerParked &&
      mainBefore &&
      multiAfter &&
      multiAfter.length > 1 &&
      multiAfter.main !== mainBefore &&
      multiAfter.hasSegment(mainBefore)
    ) {
      multiAfter.main = mainBefore
      markPendingResync(roomId)
      return
    }
    // Reader is at the tail but the gap was too wide to bridge: the fetched
    // latest page became a disjoint segment and the reader's prior tail still
    // lives upstream behind an unfetched hole. Show the latest page (don't yank
    // their segment back — they want the newest), but tell finishLoad not to
    // advance lastRead over the hole's still-unseen messages. Deliberately NOT
    // markPendingResync here, unlike the parked-reader branch above: there the
    // restore sets main to an older segment so isAtTail is false and gates the
    // retry watch; here the reader is already at the tail (main === tail), so the
    // gate is open and a re-enrolled resync would re-fire at once — on a gap
    // wider than the page budget the soft-fill stays disjoint and that loops.
    // Forward paging heals the hole; the deferred receipt is then sent by the
    // next inbound message, room re-entry, or reconnect once it is closed.
    const gapUnhealed =
      !!mainBefore &&
      !!multiAfter &&
      multiAfter.length > 1 &&
      multiAfter.main !== mainBefore &&
      multiAfter.hasSegment(mainBefore)
    await finishLoad(roomId, numberOfUnread, false, gapUnhealed)
  }

  // Backfill the open room after the socket was dead. Driven by the
  // reconnectResyncTick watch — bumped by a genuine socket reconnect AND by the
  // >60s visibility return (both via resyncAfterReconnect), so the two converge
  // on one guarded, deduped recovery instead of racing each other.
  // True while any loader that would conflict with a reconnect soft-fill is
  // busy. A blocked resync is deferred per room (markPendingResync) — never
  // dropped — and the retry watch below re-runs it once this clears.
  const resyncBlocked = computed(
    () =>
      isReconnectResyncing.value ||
      isNavigating.value ||
      isNavigatingToMessage.value ||
      isPrepending.value ||
      isBackgroundRefreshing.value ||
      isRequesting.value
  )

  const resyncOpenRoom = () => {
    const roomId = selectedRoomId.value
    if (!roomId) return
    // Don't clobber an in-flight soft-fill, navigation, pagination or room
    // refresh. Remember the deferral and retry once the blocker clears (the
    // retry watch below) — a reconnect during a slow fill can carry messages
    // newer than that fill's snapshot, so dropping it would re-strand them.
    if (resyncBlocked.value) {
      markPendingResync(roomId)
      return
    }
    clearPendingResync(roomId)
    isReconnectResyncing.value = true
    void softFillOpenRoom(roomId)
      .catch((error) => {
        // Network is often still flaky right after a reconnect; a failed
        // backfill must self-heal on the next reconnect, not throw unhandled.
        console.error('Reconnect resync soft-fill failed:', error)
      })
      .finally(() => {
        isReconnectResyncing.value = false
      })
  }

  // A socket reconnect (sleep, network drop) bumps reconnectResyncTick. This is
  // the reliable signal — it fires regardless of why the socket dropped, unlike
  // visibilitychange which never fires on laptop sleep.
  watch(
    () => imkit.reconnectResyncTick,
    () => resyncOpenRoom()
  )

  // Retry a deferred recovery once its blocker clears: every conflicting
  // loader settled AND the reader is back at the tail of the room the deferral
  // belongs to (so a latest-page reload won't yank them). Without this, a
  // reconnect that lands mid-navigation or while reading history would drop
  // the missed-message gap until the next reconnect.
  watch([selectedRoomId, resyncBlocked, isAtTail], () => {
    if (!pendingResyncRoomIds.value.has(selectedRoomId.value)) return
    if (resyncBlocked.value) return
    if (!isAtTail.value) return
    resyncOpenRoom()
  })

  const onVisibilityChange = () => {
    if (document.hidden) {
      visibilityHiddenAt = dayjs().unix()
    } else {
      const hiddenInterval = dayjs().unix() - visibilityHiddenAt
      if (hiddenInterval > 60) {
        const socket = getSocket()
        socket.connect()
        // A long hidden interval is a pseudo-reconnect. When the socket still
        // reports connected it may be half-open (mobile bg-suspend) and no
        // reconnect/auth will ever fire — force the recovery directly. When it
        // is genuinely dead, connect() leads to an auth success whose single
        // recovery path runs resyncAfterReconnect; firing it here too would
        // run the full recovery twice (a second GET /rooms + open-room refill)
        // on every long tab return.
        if (socket.connected) {
          void imkit.resyncAfterReconnect().catch((error) => {
            console.error('Visibility resync failed:', error)
          })
        }
      } else if (
        selectedRoomId.value &&
        room.value &&
        room.value.numberOfUnread > 0
      ) {
        imkit.updateLastRead(selectedRoomId.value)
        imkit.updateRoom({
          id: selectedRoomId.value,
          numberOfUnread: 0,
          isMentioned: false
        })
      }
    }
  }

  watch(
    [
      () => sortedMessages.value.length,
      () => imkit.loadingLinkPreviews.size,
      () => realMessages.value.length,
      lastRealMessage
    ],
    ([, , newRealLen], [, , oldRealLen]) => {
      if (!isInitialLoaded.value) return

      const isNewSingleMessage =
        oldRealLen !== undefined && newRealLen - oldRealLen === 1

      if (isBackgroundRefreshing.value) {
        isLatestMessageVisible.value = false
        return
      }

      if (isNewSingleMessage && lastRealMessage.value?.senderId === getUid()) {
        isLatestMessageVisible.value = false
        nextTick(() => scrollToBottom())
        return
      }

      if (!vl.value || !scrollEl.value) return
      const atBottom = isNearBottom()

      if (isNewSingleMessage) {
        isLatestMessageVisible.value = !atBottom
      }

      if (atBottom && !isNavigating.value && !isNavigatingToMessage.value) {
        nextTick(() => scrollToBottom())
      }
    }
  )

  watch(navigationTargetId, (newId) => {
    if (!newId) return

    isNavigating.value = true
    const element = document.querySelector(
      `[data-message-id="${newId}"]`
    ) as HTMLElement | null
    const listElement = scrollEl.value
    if (element && listElement) {
      const elementRect = element.getBoundingClientRect()
      const listRect = listElement.getBoundingClientRect()
      if (
        elementRect.top < listRect.top ||
        elementRect.bottom > listRect.bottom
      ) {
        const index = sortedMessages.value.findIndex(
          (message) => message.id === newId
        )
        if (index !== -1) vl.value?.scrollToIndex(index, { align: 'start' })
      }
    } else {
      const index = sortedMessages.value.findIndex(
        (message) => message.id === newId
      )
      if (index !== -1) vl.value?.scrollToIndex(index, { align: 'start' })
    }
    imkit.$patch({ navigationTargetId: '' })

    setTimeout(() => {
      const currentElement = document.querySelector(
        `[data-message-id="${newId}"]`
      ) as HTMLElement | null
      if (currentElement) {
        currentElement.classList.remove('animate-message-highlight')
        void currentElement.offsetWidth
        currentElement.classList.add('animate-message-highlight')
        currentElement.addEventListener(
          'animationend',
          () => {
            currentElement.classList.remove('animate-message-highlight')
            isNavigating.value = false
          },
          { once: true }
        )
      } else {
        isNavigating.value = false
      }
    }, 100)
  })

  onMounted(() => {
    document.addEventListener('visibilitychange', onVisibilityChange)

    if (scrollEl.value && settings.value.scrollAnchoringEnabled) {
      resizeObserver.observe(scrollEl.value)
    }
  })

  onUnmounted(() => {
    document.removeEventListener('visibilitychange', onVisibilityChange)
    resizeObserver.disconnect()
  })

  return {
    isInitialLoaded,
    isLatestMessageVisible,
    isNearBottom,
    isPrepending,
    isRequesting,
    isScrollToBottomVisible,
    onVlScroll,
    reloadData,
    scrollToBottom,
    setVl,
    sortedMessages,
    tobottom,
    totop,
    vl
  }
}
