const DropdownMenuRadioGroup = DropdownMenuRadioGroupPrimitive

const DropdownMenuSubTrigger = defineComponent({
  name: 'DropdownMenuSubTrigger',
  inheritAttrs: false,
  props: {
    class: {
      type: null,
      default: undefined
    },
    inset: {
      type: Boolean,
      default: false
    }
  },
  setup(props, { slots, attrs }) {
    return () => {
      const triggerAttrs = { ...attrs } as Record<string, unknown>
      const className = triggerAttrs.class as ClassValue
      delete triggerAttrs.class

      return h(
        DropdownMenuSubTriggerPrimitive,
        {
          ...triggerAttrs,
          class: cn(
            'data-[state=open]:bg-accent hover:bg-gray-100 dark:hover:bg-zinc-700 flex cursor-default items-center rounded-sm px-2 py-1.5 text-base outline-none select-none',
            props.inset ? 'pl-8' : '',
            className,
            props.class as ClassValue
          )
        },
        {
          default: () => [
            slots.default?.(),
            h(ChevronRight, { class: 'ml-auto h-4 w-4' })
          ]
        }
      )
    }
  }
})

