<script setup lang="ts">
import { computed } from 'vue'
import { useModal, useVfm, VueFinalModal } from 'vue-final-modal'
import { useImkitStore } from '../stores/imkit'
import DeleteMessageConfirmModal from './DeleteMessageConfirmModal.vue'
import CloseSvg from './svgs/CloseSvg.vue'
const vfm = useVfm()
const imkit = useImkitStore()
const props = defineProps<{ messageId: string; roomId: string }>()
const room = computed(() => imkit.rooms[props.roomId])
const openConfirmation = (deleteType: 'everyone' | 'me') => {
  const { open } = useModal({
    component: DeleteMessageConfirmModal,
    attrs: {
      messageId: props.messageId,
      deleteType
    }
  })
  open()
}
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-white dark:bg-zinc-800 rounded-xl p-5 flex flex-col gap-3 w-[300px]"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div
      class="mb-3 flex items-center justify-between text-xl font-semibold text-gray-700 dark:text-gray-300"
    >
      <div>&nbsp;</div>
      {{ $t('deleteMessageConfirmation') }}
      <button class="flex items-center justify-center" @click="vfm.closeAll()">
        <CloseSvg class="h-7 w-7" />
      </button>
    </div>

    <button
      class="flex h-10 w-full items-center justify-center rounded-lg border border-gray-300 text-base text-gray-700 dark:border-zinc-600 dark:text-gray-300"
      @click="openConfirmation('me')"
    >
      {{ $t('deleteForMe') }}
    </button>
    <button
      v-if="room?.isSuperuser && room.isGroup"
      class="flex h-10 w-full items-center justify-center rounded-lg bg-red-500 text-base text-white"
      @click="openConfirmation('everyone')"
    >
      {{ $t('deleteForEveryone') }}
    </button>
  </vue-final-modal>
</template>
