import { ref } from 'vue'
import type Room from '../classes/room'
import { useImkitStore } from '../stores/imkit'

export function useRoomSort() {
  const imkit = useImkitStore()
  const sortType = ref<'time' | 'unread'>('time')
  const showSortMenu = ref(false)
  const isFirstLoading = ref(true)

  const getSortString = () => '-lastMessage'

  const getSortUnreadFirst = () => (sortType.value === 'unread' ? 1 : 0)

  const getPreservedRoomIds = () => {
    const ids = new Set<string>()
    if (imkit.selectedRoomId) {
      ids.add(imkit.selectedRoomId)
    }
    for (const [roomId, isInFolder] of Object.entries(imkit.roomIdsInFolders)) {
      if (isInFolder) {
        ids.add(roomId)
      }
    }
    return ids
  }

  const settleSortedRooms = (
    fetchedRooms: Room[] | undefined,
    preservedRoomIds: Set<string>
  ) => {
    if (!fetchedRooms) return

    const rooms: Record<string, Room> = {}
    for (const room of fetchedRooms) {
      const currentRoom = imkit.rooms[room.id] ?? room
      rooms[room.id] = currentRoom
    }
    for (const roomId of preservedRoomIds) {
      const room = imkit.rooms[roomId]
      if (room) {
        rooms[roomId] = room
      }
    }

    imkit.rooms = rooms
    imkit.sortedRooms = fetchedRooms
      .map((room) => rooms[room.id] ?? room)
      .filter((room) => !imkit.roomIdsInFolders[room.id] && !room.pref?.hidden)
  }

  const updateSort = async () => {
    const sortBy = getSortString()
    const sortUnreadFirst = getSortUnreadFirst()
    const selectedRoomId = imkit.selectedRoomId
    const preservedRoomIds = getPreservedRoomIds()
    isFirstLoading.value = true
    try {
      imkit.sortBy = sortBy
      imkit.sortUnreadFirst = sortUnreadFirst
      imkit.stickyUnreadRoomIds = {}
      imkit.numberOfFetchedRooms = 0
      imkit.numberOfTotalRooms = 0
      const fetchedRooms = await imkit.fetchRooms()
      const fetchedRoomIds = new Set(
        fetchedRooms?.map((room: Room) => room.id) ?? []
      )
      if (selectedRoomId && !fetchedRoomIds.has(selectedRoomId)) {
        await imkit.fetchRoom(selectedRoomId)
      }
      await imkit.fetchRoomsInFolders()
      settleSortedRooms(fetchedRooms, preservedRoomIds)
    } finally {
      isFirstLoading.value = false
    }
  }

  const setSortType = async (type: 'time' | 'unread') => {
    sortType.value = type
    await updateSort()
  }

  return {
    sortType,
    showSortMenu,
    isFirstLoading,
    setSortType
  }
}
