<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useModal, useVfm, VueFinalModal } from 'vue-final-modal'
import { useI18n } from 'vue-i18n'
import { PaymentDetail } from '../classes/callbacks'
import { getConfig } from '../runtime/config'
import formatCurrency, { Currency } from '../utils/formatCurrency'
import PaymentErrorModal from './PaymentErrorModal.vue'
import CloseSvg from './svgs/CloseSvg.vue'

const props = defineProps<{
  uid: string
  paymentId: string
  paymentType: string
  payer: object
  payee: object
}>()

const config = getConfig()
const vfm = useVfm()
const { t, locale } = useI18n()

const getPaymentStatusMapping = (status: number) => {
  switch (status) {
    case 0:
      return t('paymentFlowUnpaid')
    case 1:
      return t('paymentFlowPaid')
    case 2:
      return t('paymentFlowRefund')
    case 3:
      return t('paymentFlowAuthorizationError')
    default:
      return t('paymentFlowUnpaid')
  }
}

const paymentDetail = ref<PaymentDetail>()
const isShowPaymentMethod = computed(() => {
  return paymentDetail.value?.data.method !== -1
})

const isLinePayVisible = computed(() => paymentDetail.value?.data.method === 0)
const isStripeVisible = computed(() => paymentDetail?.value?.data.method === 1)
const isPaypalVisible = computed(() => paymentDetail?.value?.data.method === 2)

const { open: openErrorModal } = useModal({ component: PaymentErrorModal })

const getPaymentDetailData = async () => {
  try {
    paymentDetail.value = await config.callbacks.onPaymentDetailFetched(
      props.paymentId
    )
  } catch (error) {
    console.error(error)
    openErrorModal()
  }
}

onMounted(() => {
  getPaymentDetailData()
})
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-white dark:bg-zinc-800 min-w-[400px] max-w-full rounded-xl p-5 flex flex-col gap-3 w-[300px]"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div class="relative flex flex-col items-center justify-between">
      <button
        class="absolute top-0 right-0 flex items-center justify-center"
        @click="vfm.closeAll()"
      >
        <CloseSvg class="h-6 w-6" />
      </button>
      <h1 class="text-base font-medium text-gray-700 dark:text-gray-300">
        {{ $t('paymentRequestDetail') }}
      </h1>
      <div class="mt-5 flex w-full items-baseline">
        <p
          class="mr-2 text-[18px] font-medium text-gray-700 dark:text-gray-300"
        >
          {{ paymentDetail?.data.currency }}
        </p>
        <p class="h-full min-h-[39px] text-[40px] font-medium dark:bg-zinc-800">
          {{
            formatCurrency(
              paymentDetail?.data.amount,
              paymentDetail?.data.currency as Currency
            )
          }}
        </p>
      </div>
      <div class="mt-5 flex w-full flex-col">
        <p class="text-sm font-normal text-[#6B7280] dark:text-gray-300">
          {{ $t('paymentRequestTime') }}
        </p>
        <p class="text-sm font-normal text-gray-700 dark:text-gray-300">
          {{
            paymentDetail?.data.request_at &&
            new Date(paymentDetail?.data.request_at).toLocaleString(locale)
          }}
        </p>
      </div>
      <div class="mt-4 flex w-full flex-col">
        <p class="text-sm font-normal text-[#6B7280] dark:text-gray-300">
          {{ $t('status') }}
        </p>
        <p class="text-sm font-normal text-gray-700 dark:text-gray-300">
          {{ getPaymentStatusMapping(paymentDetail?.data.status || 0) }}
          {{
            paymentDetail?.data.payment_at &&
            new Date(paymentDetail?.data.payment_at).toLocaleString(locale)
          }}
        </p>
      </div>
      <div v-if="isShowPaymentMethod" class="mt-2 flex w-full flex-col">
        <p class="text-sm mr-2 font-normal text-[#6B7280] dark:text-gray-300">
          {{ $t('paymentMethods') }}
        </p>
        <div class="mt-1 flex">
          <img
            v-if="isLinePayVisible"
            class="mr-4"
            src="../assets/linepay_logo.png"
            alt="LINE Pay Logo"
          />
          <img
            v-if="isStripeVisible"
            class="mr-4"
            src="../assets/stripe_logo.png"
            alt="Stripe Logo"
          />
          <img
            v-if="isPaypalVisible"
            class="mr-4"
            src="../assets/paypal_logo.png"
            alt="Paypal Logo"
          />
        </div>
      </div>
      <div class="mt-4 flex w-full flex-col">
        <p class="text-sm font-normal text-[#6B7280] dark:text-gray-300">
          {{ $t('paymentRequestMessage') }}
        </p>
        <p class="text-sm font-normal text-gray-700 dark:text-gray-300">
          {{
            paymentDetail?.data.note ||
            t('paymentSendPaymentRequestMessageEmpty')
          }}
        </p>
      </div>
    </div>
    <div class="mt-5 flex items-center justify-center">
      <button
        class="h-10 grow rounded-lg bg-[#02B13F] text-base text-white"
        @click="vfm.closeAll()"
      >
        {{ $t('confirm') }}
      </button>
    </div>
  </vue-final-modal>
</template>
