import { nextTick, ref, type Ref } from 'vue'
import type IMImage from '../classes/image'
import type Room from '../classes/room'
import type Settings from '../classes/settings'
import type User from '../classes/user'
import type IMVideo from '../classes/video'

type UseComposerOptions = {
  room: Ref<Room | undefined>
  users: Ref<Record<string, User>>
  settings: Ref<Settings>
  isMobile: Ref<boolean>
  input: Ref<HTMLDivElement | undefined>
  fileInput: Ref<HTMLInputElement | undefined>
  images: Ref<IMImage[]>
  imageFiles: Ref<File[]>
  videos: Ref<IMVideo[]>
  videoFiles: Ref<File[]>
  replyId: Ref<string>
  editingMessageId: Ref<string>
  sendMessage: (payload: Record<string, unknown>) => Promise<unknown>
  editMessage: (payload: {
    roomId: string
    _id: string
    message: string
  }) => Promise<unknown>
  clearReply: () => void
  clearEditing: () => void
}

const extractMessageAndMentions = (
  input: HTMLDivElement,
  room: Room,
  users: Record<string, User>
) => {
  let message = ''
  const mentions: string[] = []

  const walk = (node: Node) => {
    if (node.nodeType === Node.TEXT_NODE) {
      message += node.textContent
    } else if (node.nodeType === Node.ELEMENT_NODE) {
      const element = node as HTMLElement
      if (element.tagName === 'BR') {
        message += '\n'
      } else if (element.hasAttribute('data-at-embedded')) {
        const nickname =
          element.textContent?.trim().replace(/^@/, '').trim() || ''
        const user = Object.values(users).find(
          (member) => member.nickname === nickname
        )
        if (user) {
          mentions.push(user.id)
          message += ` @${user.id} `
        } else {
          message += element.textContent
        }
      } else if (element.tagName === 'DIV') {
        if (message.length > 0 && !message.endsWith('\n')) {
          message += '\n'
        }
        Array.from(node.childNodes).forEach(walk)
      } else {
        Array.from(node.childNodes).forEach(walk)
      }
    }
  }

  walk(input)
  message = message.trim()

  for (const uid of room.memberIds) {
    const user = users[uid]
    if (
      user &&
      message.includes(`@${user.nickname}`) &&
      !mentions.includes(user.id)
    ) {
      mentions.push(user.id)
      message = message.replaceAll(`@${user.nickname}`, `@${user.id}`)
    }
  }

  return { message, mentions }
}

export const useComposer = ({
  room,
  users,
  settings,
  isMobile,
  input,
  fileInput,
  images,
  imageFiles,
  videos,
  videoFiles,
  replyId,
  editingMessageId,
  sendMessage,
  editMessage,
  clearReply,
  clearEditing
}: UseComposerOptions) => {
  const message = ref('')
  const isComposing = ref(false)
  const showStickerPanel = ref(false)
  const showEmojiPicker = ref(false)
  const showAudioInput = ref(false)
  const stickerButtonEl = ref<HTMLElement | null>(null)
  const emojiButtonEl = ref<HTMLElement | null>(null)

  const send = async () => {
    const el = input.value
    const currentRoom = room.value
    if (!el || !currentRoom) return

    const { message: extractedMessage, mentions } = extractMessageAndMentions(
      el,
      currentRoom,
      users.value
    )
    const hasText = extractedMessage.length > 0
    const hasImages = images.value.length > 0
    const hasVideos = videos.value.length > 0

    if (!hasText && !hasImages && !hasVideos) return

    const currentReplyId = replyId.value
    const currentEditingMessageId = editingMessageId.value
    const videosToSend = hasVideos ? [...videos.value] : []
    const videoFilesToSend = hasVideos ? [...videoFiles.value] : []

    el.textContent = ''
    message.value = ''
    if (currentReplyId) {
      clearReply()
    }
    if (hasVideos) {
      videos.value = []
      videoFiles.value = []
    }

    await nextTick()

    const sendPromises: Promise<unknown>[] = []

    if (currentEditingMessageId && hasText) {
      await editMessage({
        roomId: currentRoom.id,
        _id: currentEditingMessageId,
        message: extractedMessage
      })
      clearEditing()
      if (hasImages) {
        sendPromises.push(
          sendMessage({
            roomId: currentRoom.id,
            messageType: 'image',
            images: images.value,
            files: imageFiles.value
          })
        )
        images.value = []
        imageFiles.value = []
      }
    } else if (hasText && hasImages) {
      sendPromises.push(
        sendMessage({
          roomId: currentRoom.id,
          messageType: 'mixed',
          message: extractedMessage,
          images: images.value,
          files: imageFiles.value,
          reply: currentReplyId || null,
          mentions
        })
      )
      images.value = []
      imageFiles.value = []
    } else if (hasText) {
      sendPromises.push(
        sendMessage({
          roomId: currentRoom.id,
          messageType: 'text',
          message: extractedMessage,
          reply: currentReplyId || null,
          mentions
        })
      )
    } else if (hasImages) {
      sendPromises.push(
        sendMessage({
          roomId: currentRoom.id,
          messageType: 'image',
          images: images.value,
          files: imageFiles.value
        })
      )
      images.value = []
      imageFiles.value = []
    }

    for (let index = 0; index < videosToSend.length; index++) {
      const video = videosToSend[index]
      const file = videoFilesToSend[index]
      sendPromises.push(
        sendMessage({
          roomId: currentRoom.id,
          messageType: 'video',
          video,
          file,
          width: video.width,
          height: video.height,
          duration: video.duration
        })
      )
    }

    if (sendPromises.length > 0) {
      await Promise.all(sendPromises)
    }

    input.value?.focus()
  }

  const onSelectEmoji = (emoji: { i: string }) => {
    if (input.value) {
      input.value.focus()
      document.execCommand('insertText', false, emoji.i)
    }
    showEmojiPicker.value = false
  }

  const onClickOutsideSticker = () => {
    showStickerPanel.value = false
  }

  const onClickOutsideEmoji = () => {
    showEmojiPicker.value = false
  }

  const toggleStickerPanel = () => {
    showStickerPanel.value = !showStickerPanel.value
    if (showStickerPanel.value) {
      showEmojiPicker.value = false
    }
  }

  const toggleEmojiPicker = () => {
    showEmojiPicker.value = !showEmojiPicker.value
    if (showEmojiPicker.value) {
      showStickerPanel.value = false
    }
  }

  const handleImageButtonTapped = () => {
    fileInput.value?.click()
  }

  const onCompositionstart = () => {
    isComposing.value = true
  }

  const onCompositionend = () => {
    setTimeout(() => {
      isComposing.value = false
    }, 0)
  }

  const onKeydownEnter = (event: KeyboardEvent) => {
    if (
      !isComposing.value &&
      !event.isComposing &&
      event.key === 'Enter' &&
      !event.shiftKey &&
      !isMobile.value &&
      !settings.value.sendButtonEnabled
    ) {
      event.preventDefault()
      send()
    }
  }

  // Mention-only state: input contains only contenteditable="false" children
  // and whitespace text nodes. In this state At's atomic-delete cannot trigger
  // (caret sits inside a whitespace text node with offset > 0) and
  // ensureCaretAnchor would silently regenerate the anchor on every backspace,
  // making the mention undeletable. Intercept backspace here and remove the
  // trailing mention span instead. When other editable text is present, this
  // returns false and native deletion runs as usual.
  const isMentionOnly = (el: HTMLElement) => {
    for (const node of Array.from(el.childNodes)) {
      if (node.nodeType === Node.TEXT_NODE) {
        if (!/^\s*$/.test((node as Text).data)) return false
      } else if (node.nodeType === Node.ELEMENT_NODE) {
        if ((node as HTMLElement).contentEditable !== 'false') return false
      } else {
        return false
      }
    }
    return el.querySelector('[contenteditable="false"]') !== null
  }

  const placeCaretAtTextEnd = (node: Text) => {
    const range = document.createRange()
    range.setStart(node, node.length)
    range.collapse(true)
    const sel = window.getSelection()
    sel?.removeAllRanges()
    sel?.addRange(range)
  }

  // WebKit places the caret at the far right of a contenteditable container
  // when its only children are contenteditable="false" mention spans. Keeping
  // an editable trailing text-node anchor lets WebKit position the caret
  // correctly. trim() at send time strips it from the outgoing message.
  const ensureCaretAnchor = () => {
    const el = input.value
    if (!el) return
    const last = el.lastChild
    if (
      isMentionOnly(el) &&
      last?.nodeType === Node.TEXT_NODE &&
      /^\s*$/.test((last as Text).data)
    ) {
      const anchor = last as Text
      if (!anchor.data) anchor.data = ' '
      const sel = window.getSelection()
      const range = sel?.rangeCount ? sel.getRangeAt(0) : null
      if (
        range?.collapsed &&
        range.startContainer === anchor &&
        range.startOffset === 0
      ) {
        placeCaretAtTextEnd(anchor)
      }
      return
    }
    if (
      !last ||
      last.nodeType !== Node.ELEMENT_NODE ||
      (last as HTMLElement).contentEditable !== 'false'
    ) {
      return
    }
    const anchor = document.createTextNode(' ')
    el.appendChild(anchor)
    placeCaretAtTextEnd(anchor)
  }

  const onBeforeInput = (e: InputEvent) => {
    if (e.inputType !== 'deleteContentBackward') return
    const el = input.value
    if (!el || !isMentionOnly(el)) return
    e.preventDefault()
    e.stopPropagation()
    const spans = el.querySelectorAll('[contenteditable="false"]')
    const lastSpan = spans[spans.length - 1]
    if (!lastSpan) return
    let cursor: Node | null = el.lastChild
    while (cursor) {
      const prev: Node | null = cursor.previousSibling
      el.removeChild(cursor)
      if (cursor === lastSpan) break
      cursor = prev
    }
    const range = document.createRange()
    range.selectNodeContents(el)
    range.collapse(false)
    const sel = window.getSelection()
    sel?.removeAllRanges()
    sel?.addRange(range)
    el.dispatchEvent(new Event('input', { bubbles: true }))
  }

  const onInput = () => {
    if (!input.value) return
    ensureCaretAnchor()
    const text = input.value.innerText || ''
    message.value = text
    if (!text.trim()) {
      input.value.textContent = ''
    }
  }

  const onFormatApplied = () => {
    if (input.value) {
      message.value = input.value.innerText || ''
    }
  }

  return {
    message,
    isComposing,
    showStickerPanel,
    showEmojiPicker,
    stickerButtonEl,
    emojiButtonEl,
    showAudioInput,
    send,
    onSelectEmoji,
    onClickOutsideSticker,
    onClickOutsideEmoji,
    toggleStickerPanel,
    toggleEmojiPicker,
    handleImageButtonTapped,
    onCompositionstart,
    onCompositionend,
    onKeydownEnter,
    onBeforeInput,
    onInput,
    onFormatApplied,
    ensureCaretAnchor
  }
}
