import {
  File,
  FileArchive,
  FileAudio,
  FileCode,
  FileImage,
  FileSpreadsheet,
  FileText,
  FileVideo,
  Presentation,
  type LucideIcon
} from 'lucide-vue-next'

const ICON_MAP: Record<string, LucideIcon> = {
  pdf: FileText,
  doc: FileText,
  docx: FileText,
  txt: FileText,
  rtf: FileText,
  md: FileText,
  jpg: FileImage,
  jpeg: FileImage,
  png: FileImage,
  gif: FileImage,
  webp: FileImage,
  svg: FileImage,
  bmp: FileImage,
  mp4: FileVideo,
  mov: FileVideo,
  avi: FileVideo,
  mkv: FileVideo,
  webm: FileVideo,
  mp3: FileAudio,
  wav: FileAudio,
  m4a: FileAudio,
  flac: FileAudio,
  ogg: FileAudio,
  xls: FileSpreadsheet,
  xlsx: FileSpreadsheet,
  csv: FileSpreadsheet,
  numbers: FileSpreadsheet,
  ppt: Presentation,
  pptx: Presentation,
  key: Presentation,
  zip: FileArchive,
  rar: FileArchive,
  '7z': FileArchive,
  tar: FileArchive,
  gz: FileArchive,
  js: FileCode,
  ts: FileCode,
  tsx: FileCode,
  vue: FileCode,
  py: FileCode,
  html: FileCode,
  css: FileCode,
  json: FileCode,
  xml: FileCode
}

export const getFileIcon = (extension: string): LucideIcon =>
  ICON_MAP[extension?.toLowerCase()] ?? File
