import { getConfig } from './config'

// A single in-flight forced refresh shared across concurrent callers, so a burst
// of 401s (e.g. on returning to the foreground) triggers one host refresh, not N.
let refreshing: Promise<string> | null = null

/**
 * Resolve the IMKIT auth token.
 *
 * - No `getToken` provider configured: returns the static `config.token` as-is
 *   (legacy behaviour, unchanged).
 * - Provider configured: asks the host app for the token. `forceRefresh` is
 *   passed through so the host can mint a new token after an auth failure.
 *
 * The resolved non-empty token is written back to `config.token` so the rest of
 * the SDK (header building, socket auth) keeps reading from a single source.
 */
export const resolveToken = async (forceRefresh = false): Promise<string> => {
  const provider = getConfig().getToken
  if (!provider) return getConfig().token

  try {
    if (forceRefresh) {
      // `Promise.resolve().then(provider)` turns a synchronous provider throw
      // into a rejection so it is caught here rather than escaping resolveToken.
      refreshing ??= Promise.resolve()
        .then(() => provider({ forceRefresh: true }))
        .then((token) => token ?? '')
        .finally(() => {
          refreshing = null
        })
      const token = await refreshing
      if (token) getConfig().token = token
      return token
    }

    // Proactive read for a single request. Return the host's current token but
    // do NOT mutate the shared config.token — a slow read could otherwise
    // clobber a fresher value from a concurrent forced refresh.
    return (await provider({ forceRefresh: false })) ?? getConfig().token
  } catch {
    // The provider failed. A forced refresh signals failure with '' so callers
    // show the unauthorized modal / skip reconnect; a proactive read falls back
    // to the last-known token so the request still goes out and the normal 401
    // path can handle it. resolveToken never throws.
    return forceRefresh ? '' : getConfig().token
  }
}

export const _resetTokenRefreshForTests = (): void => {
  refreshing = null
}
