import { onScopeDispose, ref, watch, type Ref } from 'vue'
import type IMImage from '../classes/image'
import { file2image } from '../classes/image'
import type User from '../classes/user'
import type IMVideo from '../classes/video'
import { file2video } from '../classes/video'
import { API } from '../enums/api'
import { getAxios } from '../runtime/axios'
import { escapeHtml } from '../utils/escapeHtml'

type FileMessagePayload = {
  roomId: string
  messageType: 'file'
  file: File
  originalUrl: string
  extra: {
    mimeType: string
    fileName: string
    bytes: number
    fileExtension: string | undefined
  }
}

type UseAttachmentUploadOptions = {
  roomId: Ref<string>
  users: Ref<Record<string, User>>
  fileSizeLimit: Ref<number>
  fileInput: Ref<HTMLInputElement | undefined>
  onOversize: () => void
  sendFile: (payload: FileMessagePayload) => Promise<unknown>
  fetchPresignedUrlByPath: (path: string) => Promise<string | null>
}

const createFilePayload = (roomId: string, file: File): FileMessagePayload => ({
  roomId,
  messageType: 'file',
  file,
  originalUrl: '',
  extra: {
    mimeType: file.type,
    fileName: file.name.split('.').slice(0, -1).join('.'),
    bytes: file.size,
    fileExtension: file.name.split('.').pop()
  }
})

export const useAttachmentUpload = ({
  roomId,
  users,
  fileSizeLimit,
  fileInput,
  onOversize,
  sendFile,
  fetchPresignedUrlByPath
}: UseAttachmentUploadOptions) => {
  const images = ref<IMImage[]>([])
  const imageFiles = ref<File[]>([])
  const videos = ref<IMVideo[]>([])
  const videoFiles = ref<File[]>([])
  const isLoadingFiles = ref(false)
  const isLoadingVideo = ref(false)
  const showImageLightbox = ref(false)
  const selectedImageIndex = ref(0)
  const showVideoLightbox = ref(false)
  const selectedVideoUrl = ref<string | null>(null)

  const resetLightboxState = () => {
    showImageLightbox.value = false
    selectedImageIndex.value = 0
    showVideoLightbox.value = false
    if (selectedVideoUrl.value) {
      URL.revokeObjectURL(selectedVideoUrl.value)
      selectedVideoUrl.value = null
    }
  }

  const fetchVideoInfo = async (videoFile: File): Promise<IMVideo> => {
    try {
      const formData = new FormData()
      formData.append('file', videoFile)
      formData.append(
        'autoUpload',
        JSON.stringify({
          bucket: 'chat',
          extra: {
            roomID: roomId.value
          }
        })
      )

      const response = await getAxios().post(API.FetchVideoInfo, formData, {
        timeout: 60000
      })

      const videoInfo = response.data?.result as {
        width: number
        height: number
        duration: number
        thumbnailUrl: string
        thumbnailId: string
        originalUrl: string
        originalId: string
      }
      const presignedThumbnailUrl = await fetchPresignedUrlByPath(
        videoInfo.thumbnailUrl
      )

      return {
        id: videoInfo.originalId,
        width: videoInfo.width,
        height: videoInfo.height,
        duration: videoInfo.duration,
        thumbnailUrl: presignedThumbnailUrl || videoInfo.thumbnailUrl,
        originalUrl: videoInfo.originalUrl,
        thumbnailFile: null
      }
    } catch (error) {
      console.error('Error fetching video info from API:', error)
      return await file2video(videoFile)
    }
  }

  const appendImages = async (selectedImageFiles: File[]) => {
    if (selectedImageFiles.length === 0) return
    isLoadingFiles.value = true
    try {
      const newImages = await Promise.all(selectedImageFiles.map(file2image))
      images.value = images.value.concat(newImages)
      imageFiles.value = imageFiles.value.concat(selectedImageFiles)
    } finally {
      isLoadingFiles.value = false
    }
  }

  const appendVideos = async (selectedVideoFiles: File[]) => {
    if (selectedVideoFiles.length === 0) return
    isLoadingVideo.value = true
    try {
      for (const videoFile of selectedVideoFiles) {
        let video
        try {
          video = await file2video(videoFile)
        } catch {
          video = await fetchVideoInfo(videoFile)
        }
        videos.value = videos.value.concat(video)
        videoFiles.value = videoFiles.value.concat(videoFile)
      }
    } finally {
      isLoadingVideo.value = false
    }
  }

  const sendOtherFiles = async (otherFiles: File[]) => {
    for (const file of otherFiles) {
      await sendFile(createFilePayload(roomId.value, file))
    }
  }

  const onFileChange = async (event: Event) => {
    const filesArray = Array.from(
      (event?.target as HTMLInputElement)?.files || []
    )
    if (filesArray.some((file) => file.size >= fileSizeLimit.value)) {
      onOversize()
      if (fileInput.value) {
        fileInput.value.value = ''
      }
      return
    }
    const files = filesArray.filter((file) => file.size < fileSizeLimit.value)

    if (files.length === 0 || files.length > 10) return

    const selectedImageFiles = files.filter((file) =>
      file.type.startsWith('image')
    )
    const selectedVideoFiles = files.filter((file) =>
      file.type.startsWith('video')
    )
    const otherFiles = files.filter(
      (file) => !file.type.startsWith('image') && !file.type.startsWith('video')
    )

    await appendImages(selectedImageFiles)
    await appendVideos(selectedVideoFiles)
    await sendOtherFiles(otherFiles)

    if (fileInput.value) {
      fileInput.value.value = ''
    }
  }

  const onDrop = async (event: DragEvent) => {
    const filesArray = Array.from((event?.dataTransfer || {}).files || [])
    if (filesArray.length === 0 || filesArray.length > 10) return
    if (filesArray.some((file) => file.size >= fileSizeLimit.value)) {
      onOversize()
      return
    }

    const droppedImageFiles = filesArray.filter((file) =>
      file.type.startsWith('image')
    )
    const droppedVideoFiles = filesArray.filter((file) =>
      file.type.startsWith('video')
    )
    const otherFiles = filesArray.filter(
      (file) => !file.type.startsWith('image') && !file.type.startsWith('video')
    )

    await appendImages(droppedImageFiles)
    await appendVideos(droppedVideoFiles)
    await sendOtherFiles(otherFiles)
  }

  const onPaste = async (event: ClipboardEvent) => {
    const clipboardData = event.clipboardData
    if (!clipboardData) return

    const files = clipboardData.files
    if (files.length > 0 && files.length <= 10) {
      if (Array.from(files).some((file) => file.size >= fileSizeLimit.value)) {
        onOversize()
        return
      }
      event.preventDefault()

      const pastedImageFiles = Array.from(files).filter((file) =>
        file.type.startsWith('image')
      )
      const pastedVideoFiles = Array.from(files).filter((file) =>
        file.type.startsWith('video')
      )

      await appendImages(pastedImageFiles)
      await appendVideos(pastedVideoFiles)
      return
    }

    const text = clipboardData.getData('text/plain')
    if (text) {
      event.preventDefault()

      let html = escapeHtml(text)
      html = html.replace(/(\s)?@([\w-]+)/g, (match, _ws, userId) => {
        const user = users.value[userId]
        if (user) {
          const safeNickname = escapeHtml(user.nickname)
          return `<span data-at-embedded="" contenteditable="false"> @${safeNickname} </span>`
        }
        return match
      })
      html = html.replace(/\n/g, '<br>')
      document.execCommand('insertHTML', false, html)
    }
  }

  const removeImageAtIndex = (index: number) => {
    images.value.splice(index, 1)
    imageFiles.value.splice(index, 1)
  }

  const removeVideoAtIndex = (index: number) => {
    videos.value.splice(index, 1)
    videoFiles.value.splice(index, 1)
  }

  const openImageLightbox = (index: number) => {
    selectedImageIndex.value = index
    showImageLightbox.value = true
  }

  const openVideoLightbox = (index: number) => {
    const file = videoFiles.value[index]
    if (!file) return
    if (selectedVideoUrl.value) {
      URL.revokeObjectURL(selectedVideoUrl.value)
    }
    selectedVideoUrl.value = URL.createObjectURL(file)
    showVideoLightbox.value = true
  }

  const handleVideoLightboxOpenChange = (val?: boolean) => {
    showVideoLightbox.value = val ?? false
    if (!showVideoLightbox.value && selectedVideoUrl.value) {
      URL.revokeObjectURL(selectedVideoUrl.value)
      selectedVideoUrl.value = null
    }
  }

  const previousImage = () => {
    if (selectedImageIndex.value > 0) {
      selectedImageIndex.value--
    }
  }

  const nextImage = () => {
    if (selectedImageIndex.value < images.value.length - 1) {
      selectedImageIndex.value++
    }
  }

  watch(roomId, (newRoomId, oldRoomId) => {
    if (newRoomId !== oldRoomId) {
      resetLightboxState()
    }
  })

  onScopeDispose(() => {
    resetLightboxState()
  })

  return {
    images,
    imageFiles,
    videos,
    videoFiles,
    isLoadingFiles,
    isLoadingVideo,
    showImageLightbox,
    selectedImageIndex,
    showVideoLightbox,
    selectedVideoUrl,
    onFileChange,
    onDrop,
    onPaste,
    removeImageAtIndex,
    removeVideoAtIndex,
    openImageLightbox,
    openVideoLightbox,
    handleVideoLightboxOpenChange,
    previousImage,
    nextImage
  }
}
