import {
  Copy,
  Pencil,
  Reply,
  Trash2,
  UndoDot,
  type LucideIcon
} from 'lucide-vue-next'
import { computed, toValue, type MaybeRefOrGetter } from 'vue'

export type ActionType =
  | 'reply'
  | 'copy'
  | 'translate'
  | 'edit'
  | 'unsend'
  | 'delete'

export interface ActionItem {
  type: ActionType
  icon: LucideIcon
  labelKey: string
  visible: boolean
  danger?: boolean
  dividerBefore?: boolean
}

export interface MessageActionOptions {
  canReply: MaybeRefOrGetter<boolean>
  canCopy: MaybeRefOrGetter<boolean>
  canTranslate?: MaybeRefOrGetter<boolean> // TODO: 實作翻譯功能
  canEdit: MaybeRefOrGetter<boolean>
  isOutgoing: MaybeRefOrGetter<boolean>
  isSuperuser: MaybeRefOrGetter<boolean>
  isGroupRoom: MaybeRefOrGetter<boolean>
}

export function useMessageActionItems(options: MessageActionOptions) {
  return computed<ActionItem[]>(() => {
    const canReply = toValue(options.canReply)
    const canCopy = toValue(options.canCopy)
    const canEdit = toValue(options.canEdit)
    const isOutgoing = toValue(options.isOutgoing)

    return [
      { type: 'reply', icon: Reply, labelKey: 'reply', visible: canReply },
      { type: 'copy', icon: Copy, labelKey: 'copy', visible: canCopy },
      { type: 'edit', icon: Pencil, labelKey: 'edit', visible: canEdit },
      {
        type: 'unsend',
        icon: UndoDot,
        labelKey: 'unsend',
        visible: isOutgoing,
        dividerBefore: true
      },
      {
        type: 'delete',
        icon: Trash2,
        labelKey: 'delete',
        visible: true,
        danger: true,
        dividerBefore: !isOutgoing
      }
    ]
  })
}
