import type Config from '../classes/config'

let _config: Config | null = null

export const setConfig = (c: Config): void => {
  _config = c
}

export const getConfig = (): Config => {
  if (!_config) throw new Error('imkit runtime not initialized (config)')
  return _config
}

export const _resetConfigForTests = (): void => {
  _config = null
}
