<script setup lang="ts">
import { AxiosProgressEvent } from 'axios'
import { AlertTriangle, Download } from 'lucide-vue-next'
import { computed, onUnmounted, ref } from 'vue'
import RadialProgress from 'vue3-radial-progress'
import { useImkitStore } from '../stores/imkit'
import { FileMessage, MessageStatus } from './../classes/message'
import { getAxios } from './../runtime/axios'
import { escapeHtml } from './../utils/escapeHtml'
import { getFileIcon } from './../utils/fileIcon'

const imkit = useImkitStore()
const props = defineProps<{ message: FileMessage }>()
const isIncoming = computed(() => props.message.isIncoming)
const uploadProgresses = computed(() => imkit.uploadProgresses)
const downloadProgresses = computed(() => imkit.downloadProgresses)
const fileIcon = computed(() => getFileIcon(props.message.fileExtension))

const downloadPercent = computed(() =>
  Math.round((downloadProgresses.value[props.message.url] ?? 0) * 100)
)

const fileSize = computed(() => {
  const size = props.message.bytes
  if (size < 1000) {
    return size + 'B'
  } else if (size < 1000 * 1000) {
    return (size / 1000).toFixed(1) + 'KB'
  } else if (size < 1000 * 1000 * 1000) {
    return (size / 1000 / 1000).toFixed(1) + 'MB'
  } else {
    return (size / 1000 / 1000 / 1000).toFixed(1) + 'GB'
  }
})

type DownloadState = 'idle' | 'downloading' | 'error'
const downloadState = ref<DownloadState>('idle')
let errorTimer: ReturnType<typeof setTimeout> | null = null
let isUnmounted = false

const download = async () => {
  if (downloadState.value !== 'idle') return
  downloadState.value = 'downloading'
  try {
    const { url, fileName, fileExtension } = props.message
    const resp = await getAxios().get(url, {
      responseType: 'blob',
      onDownloadProgress: (e: AxiosProgressEvent) => {
        if (isUnmounted) return
        const { total } = e
        if (!total) return
        imkit.mergeInto('downloadProgresses', {
          [url]: e.loaded / total
        })
      }
    })

    const blobUrl = window.URL.createObjectURL(resp.data)
    const a = document.createElement('a')
    a.href = blobUrl
    a.download = `${fileName}.${fileExtension}`
    document.body.appendChild(a)
    a.click()

    document.body.removeChild(a)
    window.URL.revokeObjectURL(blobUrl)

    if (!isUnmounted) downloadState.value = 'idle'
  } catch (error) {
    console.error(error)
    if (isUnmounted) return
    downloadState.value = 'error'
    errorTimer = setTimeout(() => {
      errorTimer = null
      if (isUnmounted) return
      downloadState.value = 'idle'
    }, 2000)
  } finally {
    if (!isUnmounted) {
      delete imkit.downloadProgresses[props.message.url]
    }
  }
}

onUnmounted(() => {
  isUnmounted = true
  if (errorTimer) {
    clearTimeout(errorTimer)
    errorTimer = null
  }
})

function escapeRegExp(string: string): string {
  return string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

const highlightKeywords = (html: string, keyword: string): string => {
  if (!keyword) return html

  const escapedKeyword = escapeRegExp(keyword)
  const regex = new RegExp(
    `(?<![a-zA-Z0-9_])${escapedKeyword}(?![a-zA-Z0-9_])`,
    'uig'
  )

  // Only highlight text content, not within HTML tags
  // Use [\s\S] instead of . to match across newlines from <br>\n
  return html.replace(/>([\s\S]*?)</g, (match, textContent) => {
    const highlighted = textContent.replace(regex, (match: string) => {
      return `<span class="bg-amber-400 text-white">${match}</span>`
    })

    return `>${highlighted}<`
  })
}

const html = computed((): string => {
  const keyword = imkit.messageSearchKeyword
  // `fileName` and `fileExtension` originate from peer-supplied message
  // `extra` payload — HTML-escape before interpolating into v-html content
  // to prevent stored XSS.
  const safeName = escapeHtml(props.message.fileName)
  const safeExt = escapeHtml(props.message.fileExtension)
  return highlightKeywords(`<span>${safeName}.${safeExt}</span>`, keyword)
})
</script>

<template>
  <div class="relative flex items-center gap-2 overflow-hidden">
    <component
      :is="fileIcon"
      :size="32"
      class="shrink-0 text-gray-600 dark:text-gray-300"
    />
    <div class="flex min-w-0 flex-1 flex-col gap-0.5 font-normal">
      <div class="multiline-ellipsis text-base" v-html="html"></div>
      <div
        class="text-base"
        :class="{ 'text-gray-500 dark:text-gray-300': isIncoming }"
      >
        {{ $t('fileSize') }}: {{ fileSize }}
      </div>
    </div>
    <button
      v-if="message.url !== ''"
      type="button"
      class="flex h-11 w-11 shrink-0 cursor-pointer items-center justify-center rounded-full hover:bg-black/5 disabled:cursor-not-allowed dark:hover:bg-white/10"
      :disabled="downloadState !== 'idle'"
      :aria-label="$t('download')"
      @click="download"
    >
      <Download
        v-if="downloadState === 'idle'"
        :size="20"
        class="text-gray-600 dark:text-gray-300"
      />
      <RadialProgress
        v-else-if="downloadState === 'downloading'"
        :diameter="36"
        :completed-steps="downloadPercent"
        :total-steps="100"
        :start-color="'#60a5fa'"
        :stop-color="'#60a5fa'"
        :stroke-width="3"
        :inner-stroke-width="3"
      >
        <span class="text-xs font-medium text-gray-600 dark:text-gray-300">
          {{ downloadPercent }}%
        </span>
      </RadialProgress>
      <AlertTriangle v-else :size="20" class="text-red-500" />
    </button>
    <template
      v-if="message.url === '' && message.status !== MessageStatus.Failed"
    >
      <div class="absolute inset-0 -m-2 bg-gray-800/50 fill-blue-300" />
      <RadialProgress
        class="absolute!"
        :diameter="48"
        :completed-steps="(uploadProgresses[message.id] ?? 0) * 100"
        :total-steps="100"
        :start-color="'#60a5fa'"
        :stop-color="'#60a5fa'"
        :stroke-width="4"
        :inner-stroke-width="4"
      >
        <span class="text-xs font-medium text-white">
          {{ Math.round((uploadProgresses[message.id] ?? 0) * 100) }}%
        </span>
      </RadialProgress>
    </template>
  </div>
</template>

<style scoped>
.multiline-ellipsis {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
  overflow-wrap: break-word;
  text-overflow: ellipsis;
}
</style>
