import { io, type Socket } from 'socket.io-client'
import Message from '../classes/message'
import Room from '../classes/room'
import User from '../classes/user'
import { getImkitStore } from '../stores/imkit'
import { getConfig } from './config'
import { resolveToken } from './token'

export interface ServerToClientEvents {
  'chat message': (res: Record<string, unknown>) => void
}

export interface ClientToServerEvents {
  auth2: (
    token: string,
    header: { CLIENT_KEY: string; Authorization: string },
    callback: (res: Record<string, unknown>) => void
  ) => void
  typing: (roomId: string) => void
}

let _socket: Socket<ServerToClientEvents, ClientToServerEvents> | null = null

// The token we last force-refreshed + reconnected for. Guards against an endless
// disconnect/connect loop when the host's proactive token keeps coming back stale
// (re-auth for the same value at most once until a successful auth re-arms it).
let lastReauthToken: string | null = null

// Whether we've completed a successful auth at least once. The first success is
// the initial connect — the app bootstrap already loads rooms/messages then, so
// resyncing would just duplicate that. Every *later* success is a reconnect
// (sleep, network drop) after which messages pushed to the dead socket were
// lost, so we resync to backfill them.
let hasAuthedOnce = false

export const getSocket = (): Socket<
  ServerToClientEvents,
  ClientToServerEvents
> => {
  if (!_socket) throw new Error('imkit runtime not initialized (socket)')
  return _socket
}

export const initSocket = (): Socket<
  ServerToClientEvents,
  ClientToServerEvents
> => {
  const socket = io(getConfig().domain, {
    forceBase64: true,
    transports: ['websocket', 'webtransport'],
    reconnection: true,
    reconnectionAttempts: Infinity,
    reconnectionDelay: 1000,
    reconnectionDelayMax: 5000
  })
  socket.on('connect', async () => {
    // Reconnects (e.g. after the tab returns to the foreground) re-run this, so
    // pull a current token from the host instead of the possibly-expired one.
    const token = await resolveToken()
    socket.emit(
      'auth2',
      token,
      {
        CLIENT_KEY: getConfig().clientKey,
        Authorization: token
      },
      (res: Record<string, unknown>) => {
        // RC 0 = authenticated; re-arm the loop guard for future failures.
        if (res?.RC === 0) {
          lastReauthToken = null
          // Backfill anything missed while the socket was dead — but only on a
          // reconnect, not the initial connect (bootstrap already loaded it).
          // The network is often still flaky right after a reconnect, so guard
          // the REST resync's promise: a failure must not become unhandled.
          if (hasAuthedOnce) {
            getImkitStore()
              .resyncAfterReconnect()
              .catch((error) => {
                console.error('[imkit] reconnect resync failed', error)
              })
          }
          hasAuthedOnce = true
          return
        }
        // Server rejects an expired/invalid token with RC 401 (Model.Result).
        // Other codes (e.g. 500) are not token problems, so leave them alone.
        if (res?.RC !== 401) return
        // Already tried to recover from this exact token; don't loop on it.
        if (token === lastReauthToken) {
          getImkitStore().cancelTrailingReconnectResync()
          return
        }
        void resolveToken(true).then((refreshed) => {
          // Only reconnect when we actually got a different token, otherwise a
          // still-bad token would loop disconnect/connect forever.
          if (refreshed && refreshed !== token) {
            lastReauthToken = token
            socket.disconnect()
            socket.connect()
            return
          }
          // Auth is dead and no fresher token exists: drop the deferred
          // trailing resync — it would only fire a doomed 401 REST call.
          getImkitStore().cancelTrailingReconnectResync()
        })
      }
    )
  })
  socket.on('disconnect', (reason: string) => {
    if (socket.active) return
    socket.connect()
    console.log(reason)
  })
  socket.on('connect_error', (error: Error) => {
    if (socket.active) return
    socket.connect()
    console.log(error.message)
  })
  socket.on('chat message', (res: Record<string, unknown>) => {
    const message = Message.createReactive(res)
    if (!message) return
    const sender = res['sender']
    if (!sender || typeof sender !== 'object') return
    const user = new User(sender)
    const callbacks = getConfig().callbacks
    callbacks?.onMessageReceived?.(message, user)
    const imkit = getImkitStore()
    imkit.mergeUsers({ [user.id]: user })
    imkit.handleMessageFromSocket({
      message,
      mentions: (res['mentions'] as string[]) ?? []
    })
  })
  socket.on('room', (res) => getImkitStore().handleRoomFromSocket(res))
  socket.on('lastRead', (res: Record<string, unknown>) => {
    const { roomID: roomId, memberID: uid, messageID: messageId } = res
    if (
      typeof roomId !== 'string' ||
      typeof uid !== 'string' ||
      typeof messageId !== 'string'
    ) {
      return
    }
    getImkitStore().handleLastReadFromSocket({ roomId, uid, messageId })
  })
  socket.on('roomPref', (res: Record<string, unknown>) => {
    const { room: roomId, ...pref } = res
    if (typeof roomId !== 'string') return
    const imkit = getImkitStore()
    imkit.updateRoom({ id: roomId, pref: pref as Room['pref'] })
    if (pref['sticky'] !== undefined) {
      imkit.aggregateRoomsAndFolders()
    }
  })
  socket.on('myPrefChange', (res) =>
    getImkitStore().handlePrefChangeFromSocket(res)
  )
  socket.on('myPrefDelete', (res) =>
    getImkitStore().handlePrefDeleteFromSocket(res)
  )
  socket.on('typing', (res) => getImkitStore().handleTypingFromSocket(res))
  socket.on('ai_streaming', (res) =>
    getImkitStore().handleAIStreamingFromSocket(res)
  )
  _socket = socket
  return socket
}

export const _resetSocketForTests = (): void => {
  _socket = null
  lastReauthToken = null
  hasAuthedOnce = false
}
