<script setup lang="ts">
import { computed, ref } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'
import { useImkitStore } from '../stores/imkit'
import AlertSvg from './svgs/AlertSvg.vue'
import CloseSvg from './svgs/CloseSvg.vue'
import LoadingSvg from './svgs/LoadingSvg.vue'

const props = defineProps<{
  memberIdToMoveOut: string
  roomId: string
}>()

const vfm = useVfm()
const imkit = useImkitStore()

const users = computed(() => imkit.users)
const showError = ref(false)
const isLoading = ref(false)

const cancelMoveOut = () => {
  vfm.closeAll()
}

const executeMoveOut = async () => {
  if (props.memberIdToMoveOut) {
    isLoading.value = true
    try {
      await imkit.removeMembers({
        roomId: props.roomId,
        uids: [props.memberIdToMoveOut]
      })
      vfm.closeAll()
    } catch (error) {
      console.error('Failed to remove member:', error)
      showError.value = true
    } finally {
      isLoading.value = false
    }
  }
}

const closeError = () => {
  showError.value = false
  vfm.closeAll()
}
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-white dark:bg-zinc-800 rounded-xl p-5 flex flex-col items-center gap-5 max-w-[350px]"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div v-if="!showError" class="relative flex flex-col items-center gap-4">
      <CloseSvg
        class="absolute right-0 h-7 w-7 cursor-pointer"
        @click="cancelMoveOut"
      />

      <AlertSvg />

      <div
        class="text-center text-xl font-medium text-gray-900 dark:text-gray-100"
      >
        {{ $t('kickOutConfirmTitle', [users[memberIdToMoveOut].nickname]) }}
      </div>

      <div class="text-center text-base text-gray-500 dark:text-gray-400">
        {{ $t('kickOutConfirmTip') }}
      </div>

      <div class="flex w-full gap-3">
        <button
          class="w-1/2 rounded-md border border-gray-300 px-4 py-2 text-gray-700 hover:bg-gray-50 dark:border-zinc-600 dark:text-gray-300 dark:hover:bg-zinc-700"
          @click="cancelMoveOut"
        >
          {{ $t('cancel') }}
        </button>
        <button
          class="flex w-1/2 items-center justify-center gap-2 rounded-md px-4 py-2 text-white"
          :class="isLoading ? 'cursor-not-allowed bg-red-300' : 'bg-[#EF4444]'"
          :disabled="isLoading"
          @click="executeMoveOut"
        >
          <LoadingSvg
            v-if="isLoading"
            class="h-4 w-4"
            :class="isLoading ? 'fill-red-300! text-white!' : 'fill-red-500'"
          />
          {{ $t('kickOutGroup') }}
        </button>
      </div>
    </div>

    <!-- Error Dialog -->
    <div v-else class="relative flex flex-col items-center gap-4">
      <CloseSvg
        class="absolute right-0 h-7 w-7 cursor-pointer"
        @click="closeError"
      />

      <AlertSvg />

      <div
        class="text-center text-xl font-medium text-gray-900 dark:text-gray-100"
      >
        {{ $t('kickOutErrorTitle') }}
      </div>

      <div class="text-center text-base text-gray-500 dark:text-gray-400">
        {{ $t('kickOutErrorDesc') }}
      </div>

      <div class="flex w-full gap-3">
        <button
          class="w-full rounded-md bg-[#EF4444] px-4 py-2 text-white"
          @click="closeError"
        >
          {{ $t('confirm') }}
        </button>
      </div>
    </div>
  </vue-final-modal>
</template>
