<script setup lang="ts">
import { computed } from 'vue'
import { AdvancedMarker, GoogleMap } from 'vue3-google-map'
import { getConfig } from '../runtime/config'
import { LocationMessage } from './../classes/message'
import { GOOGLE_MAP_DEMO_MAP_ID } from './../constants'
const props = defineProps<{ message: LocationMessage }>()
const config = getConfig()
const apiKey = config.mapApiKey
const mapId = config.mapId || GOOGLE_MAP_DEMO_MAP_ID
const center = computed(() => ({
  lat: props.message.latitude,
  lng: props.message.longitude
}))
const navigateToGoogleMap = () => {
  window.open(
    `https://www.google.com/maps/search/?api=1&query=${props.message.address}`,
    '_blank'
  )
}
</script>

<template>
  <div
    class="relative -mx-3 -my-2 flex cursor-pointer flex-col"
    @click="navigateToGoogleMap"
  >
    <google-map
      :api-key="apiKey"
      :center="center"
      :zoom="15"
      :disable-default-ui="true"
      :map-id="mapId"
      class="h-[150px] w-[250px] sm:h-[200px] sm:w-[300px]"
    >
      <AdvancedMarker :options="{ position: center }" />
    </google-map>

    <div
      class="w-[250px] p-2 text-base text-blue-500 underline sm:w-[300px] dark:text-blue-400"
    >
      {{ message.address }}
    </div>
    <div class="absolute inset-0" />
  </div>
</template>

<style scoped>
:deep(.mapdiv) > div > div {
  border-top-left-radius: 12px !important;
  border-top-right-radius: 12px !important;
  overflow: hidden;
}
</style>
