<script setup lang="ts">
import { computed, ref } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'
import Message from '../classes/message'
import { useImkitStore } from '../stores/imkit'
import CloseSvg from './svgs/CloseSvg.vue'
import LoadingSvg from './svgs/LoadingSvg.vue'

const vfm = useVfm()
const imkit = useImkitStore()
const isLoading = ref(false)

const props = defineProps<{
  messageId: string
  deleteType: 'everyone' | 'me'
}>()

const message = computed((): Message | undefined =>
  imkit.messageMultiLists
    .get(imkit.selectedRoomId)
    ?.main?.map.get(props.messageId)
)

const confirm = async () => {
  isLoading.value = true
  try {
    if (!message.value) return
    if (props.deleteType === 'everyone') {
      await imkit.deleteMessage({
        roomId: message.value.roomId,
        messageId: props.messageId
      })
    } else {
      await imkit.hideMessage({
        roomId: message.value.roomId,
        messageIds: [props.messageId]
      })
    }
    vfm.closeAll()
  } catch (error) {
    console.error('Error deleting message:', error)
  } finally {
    isLoading.value = false
  }
}
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-white dark:bg-zinc-800 min-w-[200px] max-w-full rounded-xl p-5 flex flex-col gap-3 w-[300px]"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div
      class="mb-1 flex items-center justify-between text-xl font-medium text-gray-700 dark:text-gray-300"
    >
      <span>{{ $t('confirmDeleteMessage') }}</span>
      <button class="flex items-center justify-center" @click="vfm.closeAll()">
        <CloseSvg class="h-6 w-6" />
      </button>
    </div>
    <div class="text-gray-500 dark:text-gray-400">
      <template v-if="props.deleteType === 'everyone'">
        {{ $t('deleteForEveryoneWarning') }}
      </template>
      <template v-else>
        {{ $t('deleteForMeWarning') }}
      </template>
    </div>
    <div class="flex items-center justify-center gap-2">
      <button
        class="disabled:(bg-blue-200 cursor-not-allowed) h-10 w-[100px] grow rounded-lg border border-gray-200 text-base dark:border-stone-400 dark:text-stone-400"
        @click="vfm.closeAll()"
      >
        {{ $t('cancel') }}
      </button>
      <button
        data-testid="delete-confirm-ok"
        class="flex h-10 w-[100px] grow items-center justify-center gap-2 rounded-lg text-base text-white"
        :class="isLoading ? 'cursor-not-allowed bg-red-300' : 'bg-red-500'"
        @click="confirm()"
      >
        <LoadingSvg
          v-if="isLoading"
          class="h-4 w-4"
          :class="isLoading ? 'fill-red-300! text-white!' : 'fill-red-500'"
        />
        {{ $t('delete') }}
      </button>
    </div>
  </vue-final-modal>
</template>
