<script setup lang="ts">
import Bowser from 'bowser'
import { computed, onMounted, ref } from 'vue'
import { useModal, useVfm, VueFinalModal } from 'vue-final-modal'
import { useI18n } from 'vue-i18n'
import { PaymentDetail } from '../classes/callbacks'
import { getConfig } from '../runtime/config'
import formatCurrency, { Currency } from '../utils/formatCurrency'
import PaymentErrorModal from './PaymentErrorModal.vue'
import CloseSvg from './svgs/CloseSvg.vue'

enum PaymentMethodType {
  LINE_PAY = 'linepay'
}

const props = defineProps<{
  uid: string
  paymentId: string
  paymentType: string
  payer: object
  payee: object
  availableMethods: string[]
}>()

const config = getConfig()
const { t, locale } = useI18n()
const vfm = useVfm()

const isLoading = ref(false)
const paymentDetail = ref<PaymentDetail>()
const selectedPaymentMethod = ref(
  props.availableMethods.map((method) =>
    method === 'line' ? 'linepay' : method
  )[0] || ''
)
const isLinePayVisible = computed(() => props.availableMethods.includes('line'))
const isStripeVisible = computed(() =>
  props.availableMethods.includes('stripe')
)
const isPaypalVisible = computed(() =>
  props.availableMethods.includes('paypal')
)
const isValid = computed(() => selectedPaymentMethod.value !== '')

const { open: openErrorModal } = useModal({ component: PaymentErrorModal })

const browser = Bowser.getParser(window.navigator.userAgent)
const isSafari = browser.getBrowserName() === 'Safari'

const getPaymentDetailData = async () => {
  try {
    isLoading.value = true
    paymentDetail.value = await config.callbacks.onPaymentDetailFetched(
      props.paymentId
    )
  } catch (error) {
    console.error(error)
    openErrorModal()
  } finally {
    isLoading.value = false
  }
}
const onClickPayment = async () => {
  const paymentMethod =
    selectedPaymentMethod.value === PaymentMethodType.LINE_PAY
      ? 'line'
      : selectedPaymentMethod.value

  const paymentUrl = await config.callbacks.onPaymentDetailUrlGenerated(
    props.paymentId,
    paymentMethod
  )

  // https://stackoverflow.com/questions/20696041/window-openurl-blank-not-working-on-imac-safari/39387533#39387533
  let winOpen: Window | null = null
  if (isSafari) {
    winOpen = window.open('', '_blank')
  }

  if (paymentUrl.url) {
    if (isSafari && winOpen) {
      setTimeout(() => {
        winOpen.location.href = paymentUrl.url
      }, 1000)
    } else {
      window.open(paymentUrl.url)
    }
  } else {
    openErrorModal()
  }
  vfm.closeAll()
}
const getPaymentStatusMapping = (status: number) => {
  switch (status) {
    case 0:
      return t('paymentFlowUnpaid')
    case 1:
      return t('paymentFlowPaid')
    case 2:
      return t('paymentFlowRefund')
    case 3:
      return t('paymentFlowAuthorizationError')
    default:
      return t('paymentFlowUnpaid')
  }
}

onMounted(() => {
  getPaymentDetailData()
})
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-white dark:bg-zinc-800 min-w-[400px] max-w-full rounded-xl p-5 flex flex-col gap-3 w-[300px]"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div class="relative flex flex-col items-center justify-between">
      <button
        class="absolute top-0 right-0 flex items-center justify-center"
        @click="vfm.closeAll()"
      >
        <CloseSvg class="h-6 w-6" />
      </button>
      <h1 class="text-base font-medium text-gray-700 dark:text-gray-300">
        {{ $t('paymentDetail') }}
      </h1>
      <div class="mt-5 flex w-full items-baseline">
        <p
          class="mr-2 text-[18px] font-medium text-gray-700 dark:text-gray-300"
        >
          {{ paymentDetail?.data.currency }}
        </p>
        <p class="h-full min-h-[39px] text-[40px] font-medium dark:bg-zinc-800">
          {{
            formatCurrency(
              paymentDetail?.data.amount,
              paymentDetail?.data.currency as Currency
            )
          }}
        </p>
      </div>
      <div class="mt-5 flex w-full flex-col">
        <p class="text-sm font-normal text-[#6B7280] dark:text-gray-300">
          {{ $t('paymentRequestTime') }}
        </p>
        <p class="text-sm font-normal text-gray-700 dark:text-gray-300">
          {{
            paymentDetail?.data.request_at &&
            new Date(paymentDetail?.data.request_at).toLocaleString(locale)
          }}
        </p>
      </div>
      <div class="mt-4 flex w-full flex-col">
        <p class="text-sm font-normal text-[#6B7280] dark:text-gray-300">
          {{ $t('status') }}
        </p>
        <p class="text-sm font-normal text-gray-700 dark:text-gray-300">
          {{ getPaymentStatusMapping(paymentDetail?.data.status || 0) }}
        </p>
      </div>
      <div class="mt-4 flex w-full flex-col">
        <p class="text-sm mr-2 font-normal text-[#6B7280] dark:text-gray-300">
          {{ $t('paymentMethods') }}
        </p>
        <div class="mt-1 flex">
          <label v-if="isLinePayVisible" class="mr-4 flex items-center">
            <input
              v-model="selectedPaymentMethod"
              type="radio"
              name="paymentMethod"
              value="linepay"
              class="!appearance-checkbox mr-2"
            />
            <img src="../assets/linepay_logo.png" alt="LINE Pay Logo" />
          </label>
          <label v-if="isStripeVisible" class="mr-4 flex items-center">
            <input
              v-model="selectedPaymentMethod"
              type="radio"
              name="paymentMethod"
              value="stripe"
              class="!appearance-checkbox mr-2"
            />
            <img src="../assets/stripe_logo.png" alt="Stripe Logo" />
          </label>
          <label v-if="isPaypalVisible" class="mr-4 flex items-center">
            <input
              v-model="selectedPaymentMethod"
              type="radio"
              name="paymentMethod"
              value="paypal"
              class="!appearance-checkbox mr-2"
            />
            <img src="../assets/paypal_logo.png" alt="Paypal Logo" />
          </label>
        </div>
      </div>
      <div class="mt-4 flex w-full flex-col">
        <p class="text-sm font-normal text-[#6B7280] dark:text-gray-300">
          {{ $t('paymentRequestMessage') }}
        </p>
        <p class="text-sm font-normal text-gray-700 dark:text-gray-300">
          {{
            paymentDetail?.data.note ||
            t('paymentSendPaymentRequestMessageEmpty')
          }}
        </p>
      </div>
    </div>
    <div class="mt-5 flex items-center justify-center">
      <button
        :disabled="!isValid || isLoading"
        class="h-10 grow rounded-lg bg-[#02B13F] text-base text-white disabled:cursor-not-allowed disabled:opacity-50"
        @click="onClickPayment"
      >
        {{ $t('paymentGoToPay') }}
      </button>
    </div>
  </vue-final-modal>
</template>
