<script setup lang="ts">
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { Search, X } from 'lucide-vue-next'
import { debounce, throttle } from 'throttle-debounce'
import { VList } from 'virtua/vue'
import { computed, ref, watch } from 'vue'
import { useVfm, VueFinalModal } from 'vue-final-modal'
import Room from '../classes/room'
import { API } from '../enums/api'
import { SearchType } from '../enums/searchType'
import { useImkitStore } from '../stores/imkit'
import RoomCell from './folders/RoomCell.vue'

const vfm = useVfm()
const imkit = useImkitStore()
const message = ref('')
const getSelectedAt = (roomId: string) =>
  imkit.selectedRoomIdsForCreateFolder[roomId]
const getSelectedTime = (roomId: string) => {
  const selectedAt = getSelectedAt(roomId)
  return selectedAt instanceof Date
    ? selectedAt.getTime()
    : Number.MAX_SAFE_INTEGER
}
const sortedRooms = computed<Room[]>(() => {
  if (imkit.searchKeyword) {
    return (imkit.searchRooms[SearchType.RoomName] as Room[]) || []
  }
  return (Object.values(imkit.rooms) as Room[]).sort((a: Room, b: Room) => {
    const aSelected = !!getSelectedAt(a.id)
    const bSelected = !!getSelectedAt(b.id)
    if (aSelected && !bSelected) {
      return -1
    } else if (!aSelected && bSelected) {
      return 1
    } else if (aSelected && bSelected) {
      return getSelectedTime(a.id) - getSelectedTime(b.id)
    }
    return 0
  })
})
const isValid = computed(() => message.value.length > 0)
const searchKeyword = ref('')
const isCompositting = ref(false)
const searchRooms = async () => {
  if (searchKeyword.value !== imkit.searchKeyword) {
    if (searchKeyword.value) {
      imkit.searchRoomsByKeyword(searchKeyword.value)
    } else {
      imkit.$patch({
        searchKeyword: ''
      })
    }
  }
}
const throttleSearchRooms = throttle(1000, searchRooms)
const debounceSearchRooms = debounce(500, throttleSearchRooms, {
  atBegin: false
})
watch(searchKeyword, debounceSearchRooms)
const isRequesting = computed(() => !!imkit.isRequesting[API.Search])
const submit = async () => {
  await imkit.batchSendMessage({
    message: message.value,
    messageType: 'text',
    paras: Object.keys(imkit.selectedRoomIdsForCreateFolder).map(
      (roomId: string) => ({
        room: roomId
      })
    )
  })
  imkit.$patch({
    selectedRoomIdsForCreateFolder: {},
    searchKeyword: ''
  })
}
</script>

<template>
  <vue-final-modal
    class="flex items-center justify-center"
    content-class="bg-white dark:bg-zinc-800 rounded-xl p-5 flex flex-col gap-3 w-[360px]"
    content-transition="vfm-fade"
    overlay-transition="vfm-fade"
  >
    <div
      class="mb-1 flex items-center justify-between text-xl font-medium text-gray-700 dark:text-gray-300"
    >
      {{ $t('massTexting') }}
    </div>
    <textarea
      v-model="message"
      rows="3"
      class="grow rounded-md bg-gray-100 p-2 placeholder-gray-400 outline-hidden dark:bg-zinc-700"
      :placeholder="$t('inputMessage')"
    />
    <div class="flex h-[50vh] flex-col">
      <!-- extracted header: search input -->
      <div
        class="mb-2 flex h-12 items-center gap-2 rounded-lg bg-gray-100 p-3 dark:bg-zinc-700"
      >
        <Search
          :size="24"
          class="h-6 w-6 cursor-pointer text-gray-600 dark:text-gray-300"
        />
        <div class="grow overflow-hidden">
          <input
            ref="searchInput"
            v-model="searchKeyword"
            class="bg-gray-100 placeholder-gray-400 outline-hidden dark:bg-zinc-700"
            :placeholder="$t('search')"
            @compositionstart="isCompositting = true"
            @compositionend="isCompositting = false"
          />
        </div>
        <X
          v-if="searchKeyword"
          :size="20"
          class="h-5 w-5 cursor-pointer text-gray-600 dark:text-gray-300"
          @click="
            () => {
              debounceSearchRooms.cancel({ upcomingOnly: true })
              searchKeyword = ''
              throttleSearchRooms()
            }
          "
        />
      </div>
      <!-- extracted loading skeleton -->
      <div v-if="isRequesting" class="flex flex-col gap-1">
        <div v-for="i in 10" :key="i" class="flex gap-3 p-2">
          <div class="loading h-[34px] w-[34px] rounded-xl" />
          <div class="flex grow flex-col justify-center gap-2">
            <div class="loading h-3 w-full rounded-md" />
            <div class="loading h-3 w-4/5 rounded-md" />
          </div>
        </div>
      </div>
      <!-- virtua list -->
      <VList
        v-slot="{ item }"
        :data="sortedRooms"
        :item-size="44"
        class="grow overflow-auto"
        list-class="flex flex-col gap-1.5"
      >
        <RoomCell :source="item" />
      </VList>
    </div>
    <div class="flex items-center justify-center gap-2">
      <button
        class="disabled:(bg-blue-200 cursor-not-allowed) h-10 grow rounded-lg border border-gray-200 text-base dark:border-stone-400 dark:text-stone-400"
        @click="
          () => {
            vfm.closeAll()
          }
        "
      >
        {{ $t('cancel') }}
      </button>
      <button
        class="h-10 grow rounded-lg bg-blue-400 text-base text-white"
        :class="{ 'cursor-not-allowed bg-gray-400!': !isValid }"
        :disabled="!isValid"
        @click="
          () => {
            submit()
            vfm.closeAll()
          }
        "
      >
        {{ $t('confirm') }}
      </button>
    </div>
  </vue-final-modal>
</template>
